    ('d7c001c0-c499-4c06-a756-2ceca75092d6'::uuid, 'geom', '0101000020E6100000CDBE5B79B91539400A5575BC98794140', 'SRID=4326;POINT(24.901333 34.936778)', 'fields-wd1-2026-09-26b-s010:d7c001c0-c499-4c06-a756-2ceca75092d6:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 34.94997363785849, 25.0848613594997 -> 34.936778, 24.901333', '[{"source": "https://www.wikidata.org/wiki/Q99938254", "url": "https://www.wikidata.org/wiki/Q99938254", "quote": "34°56''12.401\"N, 24°54''4.799\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=57373", "url": "https://www.megalithic.co.uk/article.php?sid=57373", "quote": "Latitude: 34.936790N Longitude: 24.901286E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikidata and the Megalithic Portal''s entry for the Yerokampos tholos tomb near Lentas give the same point (34.93678, 24.90133 / 34.93679, 24.90129), at the west edge of the hamlet of Gerokampos about 2 km west of Lendas, as the site descriptions say; the stored point lies 16.8 km to the east and is replaced.", "value_page": null}]'::jsonb),
