    ('d7c001c0-c499-4c06-a756-2ceca75092d6'::uuid, 'lon', '25.0848613594997', '24.901333', 'fields-wd1-2026-09-26b-s010:d7c001c0-c499-4c06-a756-2ceca75092d6:lon', 'fields-wd1-2026-09-26b-s010 (wd1-replace): 34.94997363785849, 25.0848613594997 -> 34.936778, 24.901333', '[{"source": "https://www.wikidata.org/wiki/Q99938254", "url": "https://www.wikidata.org/wiki/Q99938254", "quote": "34°56''12.401\"N, 24°54''4.799\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=57373", "url": "https://www.megalithic.co.uk/article.php?sid=57373", "quote": "Latitude: 34.936790N Longitude: 24.901286E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikidata and the Megalithic Portal''s entry for the Yerokampos tholos tomb near Lentas give the same point (34.93678, 24.90133 / 34.93679, 24.90129), at the west edge of the hamlet of Gerokampos about 2 km west of Lendas, as the site descriptions say; the stored point lies 16.8 km to the east and is replaced.", "value_page": null}]'::jsonb),
    ('d7c001c0-c499-4c06-a756-2ceca75092d6'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s010:d7c001c0-c499-4c06-a756-2ceca75092d6:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d7c001c0-c499-4c06-a756-2ceca75092d6'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s010:d7c001c0-c499-4c06-a756-2ceca75092d6:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0011)", "decision": "clear", "status": "MISSING", "reasoning": "English Wikipedia and minoancrete.com date the Yerokambos tholos tombs only by phase (built in Early Minoan I, still used to Middle Minoan IA) and give no year, German Wikipedia alone gives a span from about 3300 BC, and the other year statements found (geotour.gr, Wiley, JSTOR, Academia, SCS) refuse the checker or contradict each other (a tourist page says 3000 BC), so no two independent readable sources state a start year.", "value_page": null}]'::jsonb),
    ('d7c001c0-c499-4c06-a756-2ceca75092d6'::uuid, 'site_type', 'Cemetery', 'Tomb', 'fields-wd1-2026-09-26b-s010:d7c001c0-c499-4c06-a756-2ceca75092d6:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Cemetery'' -> ''Tomb''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=57373", "url": "https://www.megalithic.co.uk/article.php?sid=57373", "quote": "Site Name: Yerokampos Country: Greece Region: Crete Type: Chambered Tomb", "outcome": "found"}, {"source": "http://www.minoancrete.com/yerokambos.htm", "url": "http://www.minoancrete.com/yerokambos.htm", "quote": "The Yerokambos tholos tombs are located three kilometres to the west of the village of Lendas.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site consists of two adjoining Early Minoan tholos (beehive) tombs: the Megalithic Portal types it as a chambered tomb and minoancrete.com describes the Yerokambos tholos tombs west of Lendas; the most specific canonical type is Tomb rather than the broader Cemetery.", "value_page": null}]'::jsonb),
    ('d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s010:d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s010:d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "clear", "status": "MISSING", "reasoning": "The Megalithic Portal and Donna Nuragica attribute the Brentoni menhirs only probably to the Ozieri culture and Donna Nuragica stresses that no datable context exists; no source states a date for this site, so the stored -4000 is emptied.", "value_page": null}]'::jsonb),
    ('d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26b-s010:d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=32552", "url": "https://www.megalithic.co.uk/article.php?sid=32552", "quote": "The pre-Nuragic stone row of Brentoni consists of 3 menhirs, 2 of which are over 2 m high.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=32552", "url": "https://www.megalithic.co.uk/article.php?sid=32552", "quote": "The standing stones are located on the slope of a hill which descends towards the SE.", "outcome": "found"}, {"source": "https://www.italia-italy.org/loc2505-cosa-vedere-villa_sant_antonio-menhir-antropomorfi", "url": "https://www.italia-italy.org/loc2505-cosa-vedere-villa_sant_antonio-menhir-antropomorfi", "quote": "Ancora più importanti sono le manifestazioni artistico-religiose espresse dai grandi allineamenti di menhir antropomorfi. Le zone più interessanti per le manifestazioni neolitiche sono quelle a nord del paese, tra Cuccuru Tundu, Monte Padrillonis, Brentoni e Riu Imbessu.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal describes Brentoni as a row of three menhirs (standing stones) and italia-italy names Brentoni among the zones of menhir alignments at Villa Sant''Antonio; Standing stone is more specific than Megalithic stones.", "value_page": null}]'::jsonb),
    ('d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96'::uuid, 'source_url', 'https://m.megalithic.co.uk/article.php?sid=32552', 'https://www.megalithic.co.uk/article.php?sid=32552', 'fields-wd1-2026-09-26b-s010:d7f5b63f-d9a6-41a4-b491-7ba11aa9cc96:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://m.megalithic.co.uk/article.php?sid=32552'' -> ''https://www.megalithic.co.uk/article.php?sid=32552''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=32552", "url": "https://www.megalithic.co.uk/article.php?sid=32552", "quote": "Stone Row / Alignment in Sardinia (Sardegna) The pre-Nuragic stone row of Brentoni consists of 3 menhirs, 2 of which are over 2 m high.", "outcome": "found"}, {"source": "https://www.italia-italy.org/loc2505-cosa-vedere-villa_sant_antonio-menhir-antropomorfi", "url": "https://www.italia-italy.org/loc2505-cosa-vedere-villa_sant_antonio-menhir-antropomorfi", "quote": "Le zone più interessanti per le manifestazioni neolitiche sono quelle a nord del paese, tra Cuccuru Tundu, Monte Padrillonis, Brentoni e Riu Imbessu.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored mobile URL redirects to the Megalithic Portal''s own page for the Brentoni stone row, which is the site of this entry (no Wikipedia article exists); the canonical www URL replaces the redirect.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'geom', '0101000020E61000000B78D72F2F1605C0071FA84E675B4940', 'SRID=4326;POINT(-2.630017 50.723587)', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 50.714090187158995, -2.635832189334001 -> 50.723587, -2.630017', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6521", "url": "https://www.megalithic.co.uk/article.php?sid=6521", "quote": "Latitude: 50.723587N Longitude: 2.630017W", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q17642331", "url": "https://www.wikidata.org/wiki/Q17642331", "quote": "50°43''24.960\"N, 2°37''48.072\"W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Litton Cheney circle (the earth/timber circle scheduled as ''Earth circle S of Turner''s Farm barn'', NHLE 1004561) lies north of the village by the A35: the Megalithic Portal gives 50.723587N 2.630017W and the Wikidata item of the scheduled monument 50°43''24.960\"N 2°37''48.072\"W; the stored point is the village centre, about 1.1 km to the south.", "value_page": null}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'lat', '50.714090187158995', '50.723587', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:lat', 'fields-wd1-2026-09-26b-s010 (wd1-replace): 50.714090187158995, -2.635832189334001 -> 50.723587, -2.630017', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6521", "url": "https://www.megalithic.co.uk/article.php?sid=6521", "quote": "Latitude: 50.723587N Longitude: 2.630017W", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q17642331", "url": "https://www.wikidata.org/wiki/Q17642331", "quote": "50°43''24.960\"N, 2°37''48.072\"W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Litton Cheney circle (the earth/timber circle scheduled as ''Earth circle S of Turner''s Farm barn'', NHLE 1004561) lies north of the village by the A35: the Megalithic Portal gives 50.723587N 2.630017W and the Wikidata item of the scheduled monument 50°43''24.960\"N 2°37''48.072\"W; the stored point is the village centre, about 1.1 km to the south.", "value_page": null}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'lon', '-2.635832189334001', '-2.630017', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:lon', 'fields-wd1-2026-09-26b-s010 (wd1-replace): 50.714090187158995, -2.635832189334001 -> 50.723587, -2.630017', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6521", "url": "https://www.megalithic.co.uk/article.php?sid=6521", "quote": "Latitude: 50.723587N Longitude: 2.630017W", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q17642331", "url": "https://www.wikidata.org/wiki/Q17642331", "quote": "50°43''24.960\"N, 2°37''48.072\"W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Litton Cheney circle (the earth/timber circle scheduled as ''Earth circle S of Turner''s Farm barn'', NHLE 1004561) lies north of the village by the A35: the Megalithic Portal gives 50.723587N 2.630017W and the Wikidata item of the scheduled monument 50°43''24.960\"N 2°37''48.072\"W; the stored point is the village centre, about 1.1 km to the south.", "value_page": null}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -2200 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2200) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'period_start', '-4500', '-2200', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-4500'' -> ''-2200''', '[{"source": "https://www.thenorthernantiquarian.org/2008/10/20/litton-cheney-dorset/", "url": "https://www.thenorthernantiquarian.org/2008/10/20/litton-cheney-dorset/", "quote": "Archaeological remains from here dated from 2200-1400 BC", "outcome": "found"}, {"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "quote": "HENGIFORM MONUMENT (Late Neolithic to Early Bronze Age - 3000 BC to 1501 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "MISSING", "reasoning": "The Northern Antiquarian dates the remains from the site to 2200-1400 BC and the Dorset HER classes the monument as Late Neolithic to Early Bronze Age (3000-1501 BC), with collared urns indicating an Early Bronze Age date; the start lies in the 3000-1500 BC bucket, not the stored 4500 BC.", "value_page": null}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'site_type', 'Stone circle', 'Timber circle', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Stone circle'' -> ''Timber circle''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6521", "url": "https://www.megalithic.co.uk/article.php?sid=6521", "quote": "Evidence of earthworks are visible at the site of this timber circle, together with small barrows.", "outcome": "found"}, {"source": "https://www.thenorthernantiquarian.org/2008/10/20/litton-cheney-dorset/", "url": "https://www.thenorthernantiquarian.org/2008/10/20/litton-cheney-dorset/", "quote": "Shown on modern OS-maps as an ‘earthwork’, but ascribed elsewhere as a timber circle", "outcome": "found"}, {"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "quote": "The excavator suggested a roofed building may have stood there, though the site has subsequently been compared to timber circles.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The 1974 excavation found a small hengiform enclosure whose inner ring held 30-32 upright timbers, and any stone holes proposed by the Piggotts had been ploughed away; the Megalithic Portal and the Northern Antiquarian class it as a timber circle and the Dorset HER notes the comparison, so Timber circle fits better than Stone circle.", "value_page": null}]'::jsonb),
    ('d812b71d-59b6-4313-a4a4-830ceea2f17b'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Litton_Cheney', 'https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430', 'fields-wd1-2026-09-26b-s010:d812b71d-59b6-4313-a4a4-830ceea2f17b:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Litton_Cheney'' -> ''https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430''', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO1430", "quote": "Enclosure, possibly a henge, Litton Cheney", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6521", "url": "https://www.megalithic.co.uk/article.php?sid=6521", "quote": "Site Name: Litton Cheney", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the village and parish of Litton Cheney; the Dorset Historic Environment Record entry MDO1430 is about the prehistoric circle itself, which the Megalithic Portal also names.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d84a0080-93d7-4526-a85b-d6ca331bd239'::uuid, 'period_name', '1500 - 500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s010:d84a0080-93d7-4526-a85b-d6ca331bd239:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -4000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d84a0080-93d7-4526-a85b-d6ca331bd239'::uuid, 'period_start', '-1500', '-4000', 'fields-wd1-2026-09-26b-s010:d84a0080-93d7-4526-a85b-d6ca331bd239:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-1500'' -> ''-4000''', '[{"source": "https://pleiades.stoa.org/places/491663/json", "url": "https://pleiades.stoa.org/places/491663/json", "quote": "The site was occupied from the Late Neolithic period (ca. 4000 BCE) through 354 BCE, when it was destroyed by the armies of Philip II.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Methone_(Macedonia)", "url": "https://en.wikipedia.org/wiki/Methone_(Macedonia)", "quote": "The area around Methone was inhabited since the late Neolithic period (5000 BC to 3000 BC).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "MISSING", "reasoning": "Pleiades (after the excavators'' 2023 publication Ancient Methone 2003-2013) dates the first occupation of the site to the Late Neolithic, ca. 4000 BC, and English Wikipedia also places the first habitation in the late Neolithic; the start lies in 4500 - 3000 BC, far earlier than the stored bucket 1500 - 500 BC (the Eretrian colony of 733 BC is a later phase).", "value_page": null}]'::jsonb),
    ('d84a0080-93d7-4526-a85b-d6ca331bd239'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ancient_Methone', 'https://en.wikipedia.org/wiki/Methone_(Macedonia)', 'fields-wd1-2026-09-26b-s010:d84a0080-93d7-4526-a85b-d6ca331bd239:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Ancient_Methone'' -> ''https://en.wikipedia.org/wiki/Methone_(Macedonia)''', '[{"source": "https://en.wikipedia.org/wiki/Methone_(Macedonia)", "url": "https://en.wikipedia.org/wiki/Methone_(Macedonia)", "quote": "The ancient city of Methone was located on the northeastern shore of the Thermaic Gulf, in the northern Aegean in Greece.", "outcome": "found"}, {"source": "https://topostext.org/place/404226UMet", "url": "https://topostext.org/place/404226UMet", "quote": "Methone, Eretrian trading colony and polis near the mouth of the Haliakmon river, Nea Agathoupolis in Pieria Macedonia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored ''Ancient_Methone'' redirects to a disambiguation page; the site''s own English article is ''Methone (Macedonia)'', about the ancient city near Nea Agathoupolis in Pieria, which ToposText names as the same Methone.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Methone (Macedonia)", "unreadable": false, "wikibase_item": "Q48965819"}}]'::jsonb),
