    ('d85b55ee-afa3-423c-99d5-84149e5f8ee9'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s010:d85b55ee-afa3-423c-99d5-84149e5f8ee9:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says the stoa was built ''during the time of Pericles'' (and was absorbed into the city wall in 411 BC). The other sources found (Greece Is, the Oxford Classical Dictionary) repeat ''the time of Pericles'' without a year or century, so no two sources give a start date that can be quoted. The stored -1500 is certainly wrong for a Periclean building, so the field is emptied.", "value_page": null}]'::jsonb),
    ('d85b55ee-afa3-423c-99d5-84149e5f8ee9'::uuid, 'site_type', 'Megalithic structures', 'Archaeological site', 'fields-wd1-2026-09-26b-s010:d85b55ee-afa3-423c-99d5-84149e5f8ee9:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic structures'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Makra_Stoa", "url": "https://en.wikipedia.org/wiki/Makra_Stoa", "quote": "is an archaeological site which formed part of the urban fabric of the ancient city of Piraeus", "outcome": "found"}, {"source": "https://www.openstreetmap.org/way/391694040", "url": "https://www.openstreetmap.org/way/391694040", "quote": "historic archaeological_site", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Makra Stoa is a classical commercial stoa, a colonnaded grain store and market hall of the Piraeus Emporion. It is not a megalithic structure, and no canonical type holds a stoa or market building. Wikipedia and OpenStreetMap both record it as an archaeological site, the generic type that fits.", "value_page": null}]'::jsonb),
