    ('d9063fff-5aa2-4303-bdcb-9d683ee2b554'::uuid, 'period_name', '3000 - 1500 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s010:d9063fff-5aa2-4303-bdcb-9d683ee2b554:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -6000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-6000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d9063fff-5aa2-4303-bdcb-9d683ee2b554'::uuid, 'period_start', '-3000', '-6000', 'fields-wd1-2026-09-26b-s010:d9063fff-5aa2-4303-bdcb-9d683ee2b554:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-3000'' -> ''-6000''', '[{"source": "https://en.wikipedia.org/wiki/Baba-Dervish_settlement", "url": "https://en.wikipedia.org/wiki/Baba-Dervish_settlement", "quote": "The lower cultural layer dates back to the 6th Millennium BC.", "outcome": "found"}, {"source": "https://hal.science/hal-02136934v1/file/Berthon%202014%20Zooarch%20South%20Caucasus%20Neo%20Chalco.pdf", "url": "https://hal.science/hal-02136934v1/file/Berthon%202014%20Zooarch%20South%20Caucasus%20Neo%20Chalco.pdf", "quote": "Gargalar Tepesi and Mentesh Tepe) date from the beginning up to the third quarter of the 6th millennium B.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "The lowest layer of Baba-Dervish belongs to the Neolithic Shulaveri-Shomu culture, which Berthon (2014, after Lyonnet et al. 2012) dates for Baba-Dervish and its sister sites from the beginning to the third quarter of the 6th millennium BC, as does Wikipedia for the lower layer; older Soviet work gave the 5th or 4th millennium, but every dating puts the start before 3000 BC, so the stored 3000 - 1500 BC bucket (the Kura-Araxes layer) is not the start.", "value_page": null}]'::jsonb),
    ('d91a6d50-451d-42b1-9276-35b97c52bf5d'::uuid, 'site_type', 'Fortification', 'Fort', 'fields-wd1-2026-09-26b-s010:d91a6d50-451d-42b1-9276-35b97c52bf5d:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortification'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Milecastle", "url": "https://en.wikipedia.org/wiki/Milecastle", "quote": "A milecastle was a small fort (fortlet), a rectangular fortification built during the period of the Roman Empire", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Milecastle", "url": "https://en.wikipedia.org/wiki/Milecastle", "quote": "with the term ''Milefortlet'' being widely used to refer to similar installations that continued along the Cumbrian coast and were contemporary with the Milecastles", "outcome": "found"}, {"source": "https://co-curate.ncl.ac.uk/cumbrian-coastal-defences-roman/", "url": "https://co-curate.ncl.ac.uk/cumbrian-coastal-defences-roman/", "quote": "The Romans built a series of milefortlets, towers, and palisades down the Cumbrian coast, at the western end of Hadrian’s Wall, to help control movement across the Solway Firth estuary.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0041)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia defines milecastles and their Cumbrian counterparts, the milefortlets, as small forts (fortlets), and Co-Curate describes the milefortlets as the Roman coastal installations beyond the Wall''s end; Fort is the specific canonical type, replacing the generic Fortification.", "value_page": null}]'::jsonb),
    ('d91a6d50-451d-42b1-9276-35b97c52bf5d'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Milecastle', 'fields-wd1-2026-09-26b-s010:d91a6d50-451d-42b1-9276-35b97c52bf5d:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): None -> ''https://en.wikipedia.org/wiki/Milecastle''', '[{"source": "https://en.wikipedia.org/wiki/Milecastle", "url": "https://en.wikipedia.org/wiki/Milecastle", "quote": "with the term ''Milefortlet'' being widely used to refer to similar installations that continued along the Cumbrian coast and were contemporary with the Milecastles", "outcome": "found"}, {"source": "https://co-curate.ncl.ac.uk/cumbrian-coastal-defences-roman/", "url": "https://co-curate.ncl.ac.uk/cumbrian-coastal-defences-roman/", "quote": "The Romans built a series of milefortlets, towers, and palisades down the Cumbrian coast, at the western end of Hadrian’s Wall, to help control movement across the Solway Firth estuary.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0041)", "decision": "replace", "status": "MISSING", "reasoning": "The entry is the milefortlet class; English Wikipedia''s ''Milefortlet'' redirects to its ''Milecastle'' article, which covers the milefortlets and their numbering, so that article''s own URL is the source page; Co-Curate names the same milefortlets.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Milecastle", "unreadable": false, "wikibase_item": "Q1568283"}}]'::jsonb),
