    ('da62b3af-331d-461c-a715-d64e35870466'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Dedun', 'https://www.megalithic.co.uk/article.php?sid=6336037', 'fields-wd1-2026-09-26b-s010:da62b3af-331d-461c-a715-d64e35870466:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Dedun'' -> ''https://www.megalithic.co.uk/article.php?sid=6336037''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6336037", "url": "https://www.megalithic.co.uk/article.php?sid=6336037", "quote": "Site Name: Temple of Dedwen Country: Egypt Region: Nubia Type: Ancient Temple Nearest Town: Aswan Nearest Village: High Dam", "outcome": "found"}, {"source": "https://madainproject.com/monuments_of_new_kalabsha", "url": "https://madainproject.com/monuments_of_new_kalabsha", "quote": "The Chapel of Dedwen (or Dedun), dedicated to the Nubian serpent god Dedwen, was originally situated within the outer wall of the Temple of Kalabsha.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Wikipedia article on the god Dedun, not this site; the chapel has no Wikipedia article of its own (its Wikidata item Q138647819 has none), and the Megalithic Portal entry ''Temple of Dedwen'' at New Kalabsha (Aswan, High Dam) is about this very monument, at the same point; the Madain Project describes the same Chapel of Dedwen (or Dedun) within the outer wall of the Kalabsha temple.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
