    ('dae9bc10-f90d-45d4-9ab6-1408912b461e'::uuid, 'period_start', '1', '501', 'fields-wd1-2026-09-26b-s010:dae9bc10-f90d-45d4-9ab6-1408912b461e:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''1'' -> ''501''', '[{"source": "https://romaninscriptionsofbritain.org/inscriptions/3145", "url": "https://romaninscriptionsofbritain.org/inscriptions/3145", "quote": "6th century a.d.", "outcome": "found"}, {"source": "https://chacklepie.com/ascorpus/catvol10.php?pageNum_urls=289&totalRows_urls=298", "url": "https://chacklepie.com/ascorpus/catvol10.php?pageNum_urls=289&totalRows_urls=298", "quote": "Probably first half of sixth century; possibly late fifth century", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "replace", "status": "MISSING", "reasoning": "The current editions - Roman Inscriptions of Britain (RIB 3145) and the Corpus of Anglo-Saxon Stone Sculpture, following Sims-Williams - date the Cunorix inscription to the 6th century (probably its first half), revising Wright and Jackson''s 1968 dating of c. 460-475 that Wikipedia and CISP repeat; the start is therefore set to the 6th century AD, 501.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'geom', '0101000020E6100000CE5097EAA45422407B9513C322464540', 'SRID=4326;POINT(9.165248 41.547637)', 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 42.54793585258718, 9.165320712062023 -> 41.547637, 9.165248', '[{"source": "https://www.megalithic.co.uk/article.php?sid=9531", "url": "https://www.megalithic.co.uk/article.php?sid=9531", "quote": "Latitude: 41.547637N Longitude: 9.165248E", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "url": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "quote": "41° 32′ 51″ N, 9° 09′ 55″ E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "MISSING", "reasoning": "Vasculaghju (Vasculacciu) is the megalithic cist cemetery near Figari/Sotta in the far south of Corsica. The Megalithic Portal gives 41.547637N 9.165248E, and French Wikipedia''s list of Corsican megalithic sites gives 41° 32′ 51″ N, 9° 09′ 55″ E for the Coffres de Vasculacciu (Figari). The stored point 42.548, 9.165 is exactly one degree of latitude too far north, about 111 km away near Lucciana in Haute-Corse, so it is replaced.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'lat', '42.54793585258718', '41.547637', 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:lat', 'fields-wd1-2026-09-26b-s010 (wd1-replace): 42.54793585258718, 9.165320712062023 -> 41.547637, 9.165248', '[{"source": "https://www.megalithic.co.uk/article.php?sid=9531", "url": "https://www.megalithic.co.uk/article.php?sid=9531", "quote": "Latitude: 41.547637N Longitude: 9.165248E", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "url": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "quote": "41° 32′ 51″ N, 9° 09′ 55″ E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "MISSING", "reasoning": "Vasculaghju (Vasculacciu) is the megalithic cist cemetery near Figari/Sotta in the far south of Corsica. The Megalithic Portal gives 41.547637N 9.165248E, and French Wikipedia''s list of Corsican megalithic sites gives 41° 32′ 51″ N, 9° 09′ 55″ E for the Coffres de Vasculacciu (Figari). The stored point 42.548, 9.165 is exactly one degree of latitude too far north, about 111 km away near Lucciana in Haute-Corse, so it is replaced.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'lon', '9.165320712062023', '9.165248', 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:lon', 'fields-wd1-2026-09-26b-s010 (wd1-replace): 42.54793585258718, 9.165320712062023 -> 41.547637, 9.165248', '[{"source": "https://www.megalithic.co.uk/article.php?sid=9531", "url": "https://www.megalithic.co.uk/article.php?sid=9531", "quote": "Latitude: 41.547637N Longitude: 9.165248E", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "url": "https://fr.wikipedia.org/wiki/Sites_m%C3%A9galithiques_de_la_Corse", "quote": "41° 32′ 51″ N, 9° 09′ 55″ E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "MISSING", "reasoning": "Vasculaghju (Vasculacciu) is the megalithic cist cemetery near Figari/Sotta in the far south of Corsica. The Megalithic Portal gives 41.547637N 9.165248E, and French Wikipedia''s list of Corsican megalithic sites gives 41° 32′ 51″ N, 9° 09′ 55″ E for the Coffres de Vasculacciu (Figari). The stored point 42.548, 9.165 is exactly one degree of latitude too far north, about 111 km away near Lucciana in Haute-Corse, so it is replaced.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'period_start', '-5000', NULL, 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-5000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "clear", "status": "MISSING", "reasoning": "Only one source family - Tramoni et al.''s work, on HAL and Persée - dates the southern Corsican cists to the Middle Neolithic, ''the middle of the 5th millennium''. Even that sentence refers mainly to Tivulaghju, and it sits right on the -4500 bucket boundary. The Megalithic Portal says only ''Neolithic and Bronze Age''. No two independent sources date Vasculaghju''s start, so the field is cleared.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'site_type', 'Archaeological site', 'Necropolis', 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Archaeological site'' -> ''Necropolis''', '[{"source": "https://hal.science/hal-03583559", "url": "https://hal.science/hal-03583559", "quote": "La Nécropole mégalithique de Vasculacciu, à Figari, Corse-du-Sud, Travaux 2002-2004", "outcome": "found"}, {"source": "https://www.persee.fr/doc/bspf_0249-7638_2007_num_104_2_13557", "url": "https://www.persee.fr/doc/bspf_0249-7638_2007_num_104_2_13557", "quote": "comme pour la nécropole de Vasculacciu à Figari", "outcome": "found"}, {"source": "https://www.t4t35.fr/Megalithes/AfficheSite.aspx?NumSite=11737", "url": "https://www.t4t35.fr/Megalithes/AfficheSite.aspx?NumSite=11737", "quote": "Ce site regroupe huit coffres mégalithiques et plusieurs menhirs, tous fortement endommagés par des travaux récents.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "MISSING", "reasoning": "Inrap/CNRS excavators (HAL) and the Bulletin de la Société préhistorique française (Persée) call Vasculacciu a megalithic necropolis at Figari, and T4T35 describes it as a group of eight megalithic cists with menhirs. A cemetery of several megalithic burial cists is a Necropolis, which is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
    ('db120341-8ea9-4841-9e41-6c9d9df171b3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Vasculaghju', 'https://co.wikipedia.org/wiki/Vasculaghju', 'fields-wd1-2026-09-26b-s010:db120341-8ea9-4841-9e41-6c9d9df171b3:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Vasculaghju'' -> ''https://co.wikipedia.org/wiki/Vasculaghju''', '[{"source": "https://co.wikipedia.org/wiki/Vasculaghju", "url": "https://co.wikipedia.org/wiki/Vasculaghju", "quote": "Vasculaghju hè un situ archiulogicu situatu annantu à a cumuna di Sotta", "outcome": "found"}, {"source": "https://www.t4t35.fr/Megalithes/AfficheSite.aspx?NumSite=11737", "url": "https://www.t4t35.fr/Megalithes/AfficheSite.aspx?NumSite=11737", "quote": "Vasculaghju", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article no longer exists. The Corsican Wikipedia article ''Vasculaghju'' is the site''s own Wikipedia article, and T4T35 lists Vasculaghju as the other name of its entry Coffres de Vasculacciu (Figari).", "value_page": {"lang": "co", "problem": null, "resolved_title": "Vasculaghju", "unreadable": false, "wikibase_item": "Q7916441"}}]'::jsonb),
    ('db9de243-cfb1-43ad-941a-66e656681236'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s010:db9de243-cfb1-43ad-941a-66e656681236:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('db9de243-cfb1-43ad-941a-66e656681236'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s010:db9de243-cfb1-43ad-941a-66e656681236:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "clear", "status": "MISSING", "reasoning": "Cadw dates the hillfort only probably to the Iron Age (c.800 BC - AD 74), Coflein and the 2019-2022 excavation report speak of Iron Age construction or a Late Iron Age roundhouse without a year, and the large roundhouse may be Romano-British; no second independent source gives a start year, and the stored 3000 BC has no support.", "value_page": null}]'::jsonb),
    ('db9de243-cfb1-43ad-941a-66e656681236'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Hillfort', 'https://en.wikipedia.org/wiki/Dinas_Dinlle', 'fields-wd1-2026-09-26b-s010:db9de243-cfb1-43ad-941a-66e656681236:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Hillfort'' -> ''https://en.wikipedia.org/wiki/Dinas_Dinlle''', '[{"source": "https://en.wikipedia.org/wiki/Dinas_Dinlle", "url": "https://en.wikipedia.org/wiki/Dinas_Dinlle", "quote": "Dinas Dinlle is a hillfort in", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/95309", "url": "https://coflein.gov.uk/en/sites/95309", "quote": "Dinas Dinlle Hillfort, Llandwrog", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic Hillfort article; the English Wikipedia article Dinas Dinlle is about this Gwynedd hillfort, and Coflein''s record for the Dinas Dinlle Hillfort (NPRN 95309) names it too.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Dinas Dinlle", "unreadable": false, "wikibase_item": "Q3402467"}}]'::jsonb),
    ('db9e04a9-afe5-4541-8ae4-0d7c5b14facc'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s010:db9e04a9-afe5-4541-8ae4-0d7c5b14facc:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('db9e04a9-afe5-4541-8ae4-0d7c5b14facc'::uuid, 'period_start', '-800', NULL, 'fields-wd1-2026-09-26b-s010:db9e04a9-afe5-4541-8ae4-0d7c5b14facc:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-800'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the site by year or century: the tourism inventory copy on DePeru places it only in the Late Intermediate Period (''Periodos Intermedio Tardío''), while the archaeologist José Luis Fuentes Sadowski (Andares Magazine) merely suggests a possible Formative, Chavín-like origin of its main building; the stored 800 BC rests on no quotable independent source.", "value_page": null}]'::jsonb),
    ('db9e04a9-afe5-4541-8ae4-0d7c5b14facc'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s010:db9e04a9-afe5-4541-8ae4-0d7c5b14facc:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Pirca_Pirca,_La_Libertad", "url": "https://en.wikipedia.org/wiki/Pirca_Pirca,_La_Libertad", "quote": "is an archaeological site in Peru", "outcome": "found"}, {"source": "https://www.andaresmagazine.com/articulos-y-entrevistas/chivane%3A-el-chav%C3%ADn-perdido-de-la-sierra-liberte%C3%B1a", "url": "https://www.andaresmagazine.com/articulos-y-entrevistas/chivane%3A-el-chav%C3%ADn-perdido-de-la-sierra-liberte%C3%B1a", "quote": "se alza uno de los monumentos arqueológicos más fascinantes e impresionantes del país: el complejo arqueológico de Chivane o Pirca Pirca", "outcome": "found"}, {"source": "https://www.deperu.com/cultural/sitios-arqueologicos/complejo-arqueologico-pirca-pirca-2626", "url": "https://www.deperu.com/cultural/sitios-arqueologicos/complejo-arqueologico-pirca-pirca-2626", "quote": "Complejo arqueológico conformado por 350 construcciones de forma circular (algunas de las cuales presentan cámaras subterráneas) y una construcción rectangular de cinco pisos, situada en la parte alta del cerro Pirca Pirca (del quechua Pirca=Muro).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Sources agree only that Pirca Pirca (Chivane) is an archaeological complex on the summit of Cerro Pirca Pirca - a monumental ''castillo'' or temple plus some 350 circular stone buildings - while its function is described variously as temple, fortress or settlement; no English source calls it a town or settlement, so the generic type is the one that holds.", "value_page": null}]'::jsonb),
    ('dba260ef-3c25-4731-ac13-7eb55eb3db90'::uuid, 'period_name', '1500 - 500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s010:dba260ef-3c25-4731-ac13-7eb55eb3db90:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -4500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4500) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('dba260ef-3c25-4731-ac13-7eb55eb3db90'::uuid, 'period_start', '-1000', '-4500', 'fields-wd1-2026-09-26b-s010:dba260ef-3c25-4731-ac13-7eb55eb3db90:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-1000'' -> ''-4500''', '[{"source": "https://en.wikipedia.org/wiki/Glauberg", "url": "https://en.wikipedia.org/wiki/Glauberg", "quote": "c. 4500 BC", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Glauberg", "url": "https://de.wikipedia.org/wiki/Glauberg", "quote": "Das Plateau des Glaubergs wurde bereits seit der Jungsteinzeit in der Mitte des 5. Jahrtausends v. Chr. besiedelt.", "outcome": "found"}, {"source": "https://www.keltenwelt-glauberg.de/forschungszentrum/der-glauberg/", "url": "https://www.keltenwelt-glauberg.de/forschungszentrum/der-glauberg/", "quote": "Spätestens ab der Jungsteinzeit ließen sich im 5. Jahrtausend v. Chr. (Rössener Kultur) auf dem 8 Hektar großen Plateau am Rande der fruchtbaren Wetterau die ersten Ackerbauen und Viehzüchter nieder.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia (English: first settlement of the plateau by the Rössen culture, c. 4500 BC; German: settled since the middle of the 5th millennium BC) and the Keltenwelt am Glauberg research centre (first farmers on the plateau in the 5th millennium BC, Rössen culture) date the start of occupation to the Middle Neolithic; the Urnfield fortification of the 10th-9th century BC behind the stored -1000 came much later, so the start is c. 4500 BC.", "value_page": null}]'::jsonb),
    ('dba260ef-3c25-4731-ac13-7eb55eb3db90'::uuid, 'site_type', 'Fortress/citadel', 'Fortification', 'fields-wd1-2026-09-26b-s010:dba260ef-3c25-4731-ac13-7eb55eb3db90:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Fortification''', '[{"source": "https://en.wikipedia.org/wiki/Glauberg", "url": "https://en.wikipedia.org/wiki/Glauberg", "quote": "Extensive fortifications were erected.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=13009", "url": "https://www.megalithic.co.uk/article.php?sid=13009", "quote": "Fortification wall of Celtic Hillfort in Hessen dating to 500 BCE.", "outcome": "found"}, {"source": "https://www.keltenwelt-glauberg.de/forschungszentrum/der-glauberg/", "url": "https://www.keltenwelt-glauberg.de/forschungszentrum/der-glauberg/", "quote": "Das gesamte Bergplateau wurde gegen Ende des 6. Jahrhunderts v. Chr. mit einer holzverstärkten Steinmauer (sog. Pfostenschlitzmauer) umgeben (Mauer I).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe the Glauberg as a hillfort: a plateau enclosed by successive ramparts and walls (Urnfield, late Hallstatt/early La Tène, early medieval, Staufer), with princely burial mounds at its foot. Fortification is the canonical type for a walled hillfort; none of the sources calls it a fortress or citadel.", "value_page": null}]'::jsonb),
    ('dbbef6f8-f2bb-4ea3-9691-90c09205f678'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Siega_Verde', 'https://es.wikipedia.org/wiki/Siega_Verde', 'fields-wd1-2026-09-26b-s010:dbbef6f8-f2bb-4ea3-9691-90c09205f678:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Siega_Verde'' -> ''https://es.wikipedia.org/wiki/Siega_Verde''', '[{"source": "https://es.wikipedia.org/wiki/Siega_Verde", "url": "https://es.wikipedia.org/wiki/Siega_Verde", "quote": "Siega Verde es un sitio arqueológico al aire libre localizado en las pedanías españolas de Serranillo (Villar de la Yegua)", "outcome": "found"}, {"source": "https://www.jcyl.es/jcyl/patrimoniocultural/GuiaLugaresArqueologicos/salamanca/01salamanca/index.html", "url": "https://www.jcyl.es/jcyl/patrimoniocultural/GuiaLugaresArqueologicos/salamanca/01salamanca/index.html", "quote": "Entre estos parajes con arte rupestre al aire libre ocupa un papel principal Siega Verde, declarado Patrimonio Mundial el día 1 de Agosto de 2010.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia URL is a redirect to the article on the whole transboundary World Heritage Site (Côa Valley and Siega Verde), not this site; the Spanish Wikipedia article is the site''s own article (the item''s eswiki sitelink) and is about Siega Verde itself, which the Castilla y León heritage guide also describes.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Siega Verde", "unreadable": false, "wikibase_item": "Q2717874"}}]'::jsonb),
    ('dbd288ca-6fcc-4eaa-a346-a7b233b33955'::uuid, 'site_type', 'Necropolis/tombs complex', 'Tomb', 'fields-wd1-2026-09-26b-s010:dbd288ca-6fcc-4eaa-a346-a7b233b33955:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Necropolis/tombs complex'' -> ''Tomb''', '[{"source": "https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)", "url": "https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)", "quote": "The Altendorf tomb (German: Steinkammergrab von Altendorf) was an important megalithic tomb at Altenburg near Naumburg, northern Hesse, Germany. It was a gallery grave belonging to the Late Neolithic Wartberg culture.", "outcome": "found"}, {"source": "https://www.eaz-journal.org/index.php/jna/article/view/179", "url": "https://www.eaz-journal.org/index.php/jna/article/view/179", "quote": "The re-analyses of the Altendorf gallery grave reveal three different phases of inhumation burial practices: collective burials of a whole community (3250–3100 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia and the Journal of Neolithic Archaeology both describe Altendorf as a single megalithic gallery grave (the Megalithic Portal lists it as a passage grave). It is one collective tomb, not a necropolis of several tombs, and not a sculpture as Wikidata has it, so the type is Tomb.", "value_page": null}]'::jsonb),
    ('dc277dc8-5631-484f-b07a-d1462403dd92'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s010:dc277dc8-5631-484f-b07a-d1462403dd92:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('dc277dc8-5631-484f-b07a-d1462403dd92'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s010:dc277dc8-5631-484f-b07a-d1462403dd92:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Historic England listing (quoted by Co-Curate) date the cairn and stone only as ''Late Neolithic/Early Bronze Age''; no source gives a year, century or millennium for this monument, so the stored -4500 (which the Late Neolithic does not even reach) is cleared.", "value_page": null}]'::jsonb),
    ('dc7674a8-0723-455e-ab0b-9378c4491da9'::uuid, 'site_type', 'Megalithic stones', 'Dolmen', 'fields-wd1-2026-09-26b-s010:dc7674a8-0723-455e-ab0b-9378c4491da9:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic stones'' -> ''Dolmen''', '[{"source": "https://en.wikipedia.org/wiki/Blue_Bell_Hill", "url": "https://en.wikipedia.org/wiki/Blue_Bell_Hill", "quote": "The Blue Bell Hill Dolmen was a now lost member of the group of Neolithic chamber tombs", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=19625", "url": "https://www.megalithic.co.uk/article.php?sid=19625", "quote": "Type: Burial Chamber or Dolmen", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal describe the site as the Blue Bell Hill Dolmen, a sarsen burial chamber of the Medway group (the Wikidata item is only the hill); Dolmen is the most specific canonical type, narrower than Megalithic stones.", "value_page": null}]'::jsonb),
    ('dc7674a8-0723-455e-ab0b-9378c4491da9'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Blue_Bell_Hill', 'https://heritage.kent.gov.uk/Monument/MKE2504', 'fields-wd1-2026-09-26b-s010:dc7674a8-0723-455e-ab0b-9378c4491da9:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Blue_Bell_Hill'' -> ''https://heritage.kent.gov.uk/Monument/MKE2504''', '[{"source": "https://heritage.kent.gov.uk/Monument/MKE2504", "url": "https://heritage.kent.gov.uk/Monument/MKE2504", "quote": "The Blue Bell Hill Dolmen, Kent, destroyed.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Blue_Bell_Hill", "url": "https://en.wikipedia.org/wiki/Blue_Bell_Hill", "quote": "The Blue Bell Hill Dolmen was a now lost member of the group of Neolithic chamber tombs", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the chalk hill (the dolmen''s own article was merged into it as a section); the Kent Historic Environment Record entry ''TQ 76 SW 22 - Site of Neolithic chambered tomb, Blue Bell Hill, Burham'' is the register entry for the dolmen itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('dcfca154-a46b-4515-849a-e9248d470e07'::uuid, 'source_url', 'www.historyhit.com/locations/trajan-arch-of-merida/', 'https://es.wikipedia.org/wiki/Arco_de_Trajano_(M%C3%A9rida)', 'fields-wd1-2026-09-26b-s010:dcfca154-a46b-4515-849a-e9248d470e07:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''www.historyhit.com/locations/trajan-arch-of-merida/'' -> ''https://es.wikipedia.org/wiki/Arco_de_Trajano_(M%C3%A9rida)''', '[{"source": "https://es.wikipedia.org/wiki/Arco_de_Trajano_(M%C3%A9rida)", "url": "https://es.wikipedia.org/wiki/Arco_de_Trajano_(M%C3%A9rida)", "quote": "En 1912, el Arco de Trajano fue declarado Monumento nacional", "outcome": "found"}, {"source": "https://www.historyhit.com/locations/trajan-arch-of-merida/", "url": "https://www.historyhit.com/locations/trajan-arch-of-merida/", "quote": "The Trajan Arch of Merida is a UNESCO listed Ancient Roman granite gateway.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored History Hit link lacks its scheme; the arch has no English article (the English title redirects to the Provincial Forum), so its own Spanish Wikipedia article, which names the Arco de Trajano of Mérida, replaces it; History Hit confirms the same monument.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Arco de Trajano (Mérida)", "unreadable": false, "wikibase_item": "Q30919150"}}]'::jsonb),
    ('dd0f3348-710e-4e66-b50e-45bd71b61e12'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s010:dd0f3348-710e-4e66-b50e-45bd71b61e12:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Badbury_Hill", "url": "https://en.wikipedia.org/wiki/Badbury_Hill", "quote": "The summit of the hill is the site of an Iron Age hill fort known as Badbury Camp.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=19243", "url": "https://www.megalithic.co.uk/article.php?sid=19243", "quote": "The Iron Age hillfort on Badbury Hill is partly leveled", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal (independent families) both describe the site as an Iron Age hill fort (Badbury Camp), a defended enclosure rather than a fortress or citadel, so the canonical type is Fort.", "value_page": null}]'::jsonb),
    ('dd0f3348-710e-4e66-b50e-45bd71b61e12'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Badbury_Hill', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA129595', 'fields-wd1-2026-09-26b-s010:dd0f3348-710e-4e66-b50e-45bd71b61e12:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Badbury_Hill'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA129595''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA129595", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA129595", "quote": "Badbury Hill Fort, Great Coxwell, Buscot and Coleshill Estates", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=19243", "url": "https://www.megalithic.co.uk/article.php?sid=19243", "quote": "The Iron Age hillfort on Badbury Hill is partly leveled", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill; the National Trust''s heritage record (the fort is a scheduled monument in its care) is about Badbury Hill Fort itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('dde17f3b-8489-41f6-83e4-7cb23927e266'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Villa', 'fields-wd1-2026-09-26b-s010:dde17f3b-8489-41f6-83e4-7cb23927e266:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Villa''', '[{"source": "https://marpositano.it/web/villa-romana/", "url": "https://marpositano.it/web/villa-romana/", "quote": "Si tratta di una classica Villa “Marittima” dell’epoca romana", "outcome": "found"}, {"source": "https://catalogo.beniculturali.it/detail/ArchaeologicalProperty/1500875172", "url": "https://catalogo.beniculturali.it/detail/ArchaeologicalProperty/1500875172", "quote": "Villa romana di Positano (villa, struttura abitativa)", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "The museum of the site calls it a classic Roman maritime villa, and the national Catalogo generale dei Beni Culturali lists the site as ''Villa romana di Positano (villa, struttura abitativa)''; the most specific canonical type for a Roman villa is Villa, not the wider Residence/villa/farmhouse.", "value_page": null}]'::jsonb),
    ('dde17f3b-8489-41f6-83e4-7cb23927e266'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Positano', 'https://it.wikipedia.org/wiki/Museo_archeologico_romano_Santa_Maria_Assunta', 'fields-wd1-2026-09-26b-s010:dde17f3b-8489-41f6-83e4-7cb23927e266:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Positano'' -> ''https://it.wikipedia.org/wiki/Museo_archeologico_romano_Santa_Maria_Assunta''', '[{"source": "https://it.wikipedia.org/wiki/Museo_archeologico_romano_Santa_Maria_Assunta", "url": "https://it.wikipedia.org/wiki/Museo_archeologico_romano_Santa_Maria_Assunta", "quote": "Il percorso di visita include un ambiente riccamente affrescato, appartenente ad una villa di epoca romana, le cripte e alcune sale annesse alla collegiata di Santa Maria Assunta dove sono esposti i reperti rinvenuti durante gli scavi", "outcome": "found"}, {"source": "https://catalogo.beniculturali.it/detail/ArchaeologicalProperty/1500875172", "url": "https://catalogo.beniculturali.it/detail/ArchaeologicalProperty/1500875172", "quote": "Villa romana di Positano (villa, struttura abitativa)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the comune of Positano; the Italian Wikipedia article on the MAR is about the Roman villa of Positano exhibited in situ under Santa Maria Assunta, which the national heritage catalogue lists as the Villa romana di Positano.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Museo archeologico romano Santa Maria Assunta", "unreadable": false, "wikibase_item": "Q86207204"}}]'::jsonb),
