    ('de42523e-9322-4dba-9448-016174872c48'::uuid, 'site_type', 'Pyramid complex', 'City/town/settlement, Pyramid complex', 'fields-wd1-2026-09-26b-s010:de42523e-9322-4dba-9448-016174872c48:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Pyramid complex'' -> ''City/town/settlement, Pyramid complex''', '[{"source": "https://en.wikipedia.org/wiki/Teotihuacan", "url": "https://en.wikipedia.org/wiki/Teotihuacan", "quote": "Teotihuacan is known today as the site of many of the most architecturally significant Mesoamerican pyramids built in the pre-Columbian Americas", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=16610", "url": "https://www.megalithic.co.uk/article.php?sid=16610", "quote": "Teotihuacan was the largest pre-Columbian city in the Americas.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Megalithic Portal describe Teotihuacan as an ancient city, the largest of the pre-Columbian Americas, whose best-known monuments are the pyramids of the Sun and the Moon; the combined type City/town/settlement, Pyramid complex holds both, where Pyramid complex alone leaves out the city.", "value_page": null}]'::jsonb),
