    ('df4987a2-4247-4be4-8d1c-89e3e6f816fe'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Long_Mountain_(Powys)', 'https://cy.wikipedia.org/wiki/Caer_Digoll', 'fields-wd1-2026-09-26b-s010:df4987a2-4247-4be4-8d1c-89e3e6f816fe:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Long_Mountain_(Powys)'' -> ''https://cy.wikipedia.org/wiki/Caer_Digoll''', '[{"source": "https://cy.wikipedia.org/wiki/Caer_Digoll", "url": "https://cy.wikipedia.org/wiki/Caer_Digoll", "quote": "Mae Bryngaer Caer Digoll yn fryngaer Geltaidd sy''n perthyn i Oes yr Haearn", "outcome": "found"}, {"source": "https://heneb.org.uk/project/beacon-ring/", "url": "https://heneb.org.uk/project/beacon-ring/", "quote": "Clwyd-Powys Archaeological Trust acquired the magnificent Beacon Ring hillfort, which crowns Long Mountain in eastern Montgomeryshire, Powys.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the hill Long Mountain; the hillfort has no English article, but the Welsh Wikipedia article Caer Digoll is about the Iron Age hillfort itself (Cadw MG011, near Trelystan), which Heneb independently names as the Beacon Ring hillfort on Long Mountain.", "value_page": {"lang": "cy", "problem": null, "resolved_title": "Caer Digoll", "unreadable": false, "wikibase_item": "Q13126475"}}]'::jsonb),
    ('df612ef7-118e-442d-a451-e39062607faf'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s010:df612ef7-118e-442d-a451-e39062607faf:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -470 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-470) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('df612ef7-118e-442d-a451-e39062607faf'::uuid, 'period_start', '-1500', '-470', 'fields-wd1-2026-09-26b-s010:df612ef7-118e-442d-a451-e39062607faf:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-1500'' -> ''-470''', '[{"source": "https://ukhillfortlidar.myportfolio.com/midsummer-hill", "url": "https://ukhillfortlidar.myportfolio.com/midsummer-hill", "quote": "Radiocarbon dates yield construction start circa 470BC.", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "quote": "Excavations within the hillfort have revealed Neolithic, Bronze Age and Iron Age pottery and artefacts that show that the hillfort was established in the 5th century BC and was occupied for about 500 years.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "MISSING", "reasoning": "The National Trust Heritage Record says the excavations show the hillfort was established in the 5th century BC, and the UK Hillfort Lidar page gives radiocarbon dates for the start of construction around 470 BC (Wikipedia''s c. 390 BC lies in the same bucket); the stored c. 1500 BC is unsupported, so the start is replaced by c. 470 BC in the 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('df612ef7-118e-442d-a451-e39062607faf'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s010:df612ef7-118e-442d-a451-e39062607faf:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Hollybush_Hill", "url": "https://en.wikipedia.org/wiki/Hollybush_Hill", "quote": "It is the site of an Iron Age hill fort which spans Hollybush Hill and Midsummer Hill.", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "quote": "English Heritage''s most recent survey in 1999 recorded over 483 hut platforms within the hill fort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the National Trust Heritage Record both describe the site as an Iron Age multivallate hill fort spanning Hollybush and Midsummer Hills; the most specific canonical type for it is Fort, not fortress/citadel.", "value_page": null}]'::jsonb),
    ('df612ef7-118e-442d-a451-e39062607faf'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Hollybush_Hill', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221', 'fields-wd1-2026-09-26b-s010:df612ef7-118e-442d-a451-e39062607faf:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Hollybush_Hill'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "quote": "with little result except for finds of brick and charcoal fragments, and some further of the circular hollows on Hollybush Hill.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Hollybush_Hill", "url": "https://en.wikipedia.org/wiki/Hollybush_Hill", "quote": "It is the site of an Iron Age hill fort which spans Hollybush Hill and Midsummer Hill.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Wikipedia stub on the hill; the site is the Midsummer Hill Camp hillfort on Midsummer and Hollybush Hills, and the National Trust Heritage Record of that scheduled hillfort, a heritage register entry, replaces it; Wikipedia names the same hillfort spanning Hollybush Hill.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s010:dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -1500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7'::uuid, 'period_start', '-3000', '-1500', 'fields-wd1-2026-09-26b-s010:dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-3000'' -> ''-1500''', '[{"source": "https://en.wikipedia.org/wiki/Cumbemayo", "url": "https://en.wikipedia.org/wiki/Cumbemayo", "quote": "Built around 1500 B.C.E, it comprises aqueducts", "outcome": "found"}, {"source": "https://www.perunorth.com/cumbe-mayo-cajamarca", "url": "https://www.perunorth.com/cumbe-mayo-cajamarca", "quote": "Cumbemayo has three fascinating archaeological features, thought to have been built between 1500 and 1000 BC", "outcome": "found"}, {"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=647", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=647", "quote": "El acueducto es una singular obra de ingeniería hidráulica que pertenece al período inicial de la cultura Cajamarca (1000 a.C.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates Cumbemayo to around 1500 BC, a northern-Peru tour operator''s site guide to 1500-1000 BC, and Peru''s MINCETUR inventory assigns the aqueduct to the initial Cajamarca period (1000 BC); all place the start in 1500 - 500 BC, not in the stored 3000 - 1500 BC bucket.", "value_page": null}]'::jsonb),
    ('dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7'::uuid, 'site_type', 'Petroglyphs', 'Aqueduct', 'fields-wd1-2026-09-26b-s010:dfb2dbf1-38da-4bbc-834e-d956c3a8a8d7:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Petroglyphs'' -> ''Aqueduct''', '[{"source": "https://en.wikipedia.org/wiki/Cumbemayo", "url": "https://en.wikipedia.org/wiki/Cumbemayo", "quote": "One of the main attractions of Cumbemayo, or \"Narrow River\" in Cajamarca Quechua, is the aqueduct.", "outcome": "found"}, {"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=647", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=647", "quote": "El conjunto se compone de tres importantes grupos arqueológicos: el acueducto, el santuario y las cuevas.", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cumbemayo near Cajamarca, Peru, is a pre-Inca archaeological complex whose principal monument is the aqueduct, an open canal cut in volcanic rock (English Wikipedia; the Peruvian national tourism inventory lists the acueducto first among its three groups, with the sanctuary and the caves that carry the engravings). Petroglyphs are only a secondary part of the site, so the stored type Petroglyphs is replaced by the more fitting Aqueduct.", "value_page": null}]'::jsonb),
    ('dfed1a81-7d54-4f3b-b1ab-e2be649acc2f'::uuid, 'site_type', 'Fortress/citadel', 'Fortification', 'fields-wd1-2026-09-26b-s010:dfed1a81-7d54-4f3b-b1ab-e2be649acc2f:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Fortification''', '[{"source": "https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)", "url": "https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)", "quote": "It has been the site of many historic and pre-historic constructions, including a Celtic hilltop fortification, a Roman sacred precinct, several medieval monasteries, modern lookout towers and the Heidelberg Thingstätte", "outcome": "found"}, {"source": "https://www.keltenland-bw.de/keltenland/heiligenberg-mit-kurpfaelzischem-museum/", "url": "https://www.keltenland-bw.de/keltenland/heiligenberg-mit-kurpfaelzischem-museum/", "quote": "Der Heiligenberg bei Heidelberg zählt mit seinen mächtigen Befestigungswällen aus dem 5. und 4. Jahrhundert vor Christus zu den größten keltischen Befestigungsanlagen im südlichen Mitteleuropa.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe a Celtic hilltop fortification: a double ring of ramparts around a large hill settlement (Befestigungsanlage), not a fortress or citadel. Fortification is the type that holds what they say.", "value_page": null}]'::jsonb),
    ('e00a1e45-3c66-48f4-8cac-3169146aad21'::uuid, 'site_type', 'Temple complex', 'Palace', 'fields-wd1-2026-09-26b-s010:e00a1e45-3c66-48f4-8cac-3169146aad21:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Temple complex'' -> ''Palace''', '[{"source": "https://en.wikipedia.org/wiki/Persepolis", "url": "https://en.wikipedia.org/wiki/Persepolis", "quote": "The city, acting as a major centre of the empire, housed a palace complex and citadel designed to serve as the focal point for governance and ceremonial activities.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Persepolis", "url": "https://en.wikipedia.org/wiki/Persepolis", "quote": "Persepolis is more often referred to as a complex rather than a \"city\" in the usual sense.", "outcome": "found"}, {"source": "https://www.iranicaonline.org/articles/persepolis/", "url": "https://www.iranicaonline.org/articles/persepolis/", "quote": "chose a promontory of the “Royal Hill” at the foot of a mountain to the east of the plain to serve as the site for a new palace complex forming the citadel of the city of Pārsa.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Encyclopaedia Iranica both describe the site on the terrace as the Achaemenid royal palace complex (Apadana, palaces of Darius and Xerxes, throne hall), and Wikipedia notes it is referred to as a complex rather than a city; nothing identifies it as a temple complex, so Palace is the most specific fitting type.", "value_page": null}]'::jsonb),
    ('e06caf0a-2a7c-44d5-8cdb-5473d995f896'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Temple_of_the_Moon_(Peru)', 'https://en.wikipedia.org/wiki/Amaru_Marka_Wasi', 'fields-wd1-2026-09-26b-s010:e06caf0a-2a7c-44d5-8cdb-5473d995f896:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Temple_of_the_Moon_(Peru)'' -> ''https://en.wikipedia.org/wiki/Amaru_Marka_Wasi''', '[{"source": "https://en.wikipedia.org/wiki/Amaru_Marka_Wasi", "url": "https://en.wikipedia.org/wiki/Amaru_Marka_Wasi", "quote": "or Templo de la Luna (Temple of the Moon) is an archaeological site in Peru.", "outcome": "found"}, {"source": "https://trekero.com/blog/templo-de-la-luna-cusco", "url": "https://trekero.com/blog/templo-de-la-luna-cusco", "quote": "Entre los años 1428 y 1532 d.C., los incas esculpieron el Templo de la Luna directamente sobre una enorme roca. Según cronistas, este espacio servía como adoratorio, donde se honraban a sus dioses mediante rituales sagrados. El investigador Germán Zecenarro lo identificó como la séptima huaca llamada Amaru Markawasi.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0114)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is the Temple of the Moon on Huayna Picchu at Machu Picchu, another site; the Cusco Templo de la Luna has its own English article under the name Amaru Marka Wasi (same point near Qenqo), and Trekero confirms the Templo de la Luna is the huaca Amaru Markawasi.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Amaru Marka Wasi", "unreadable": false, "wikibase_item": "Q16827793"}}]'::jsonb),
    ('e149d164-394f-4528-a19b-19dd92991b03'::uuid, 'geom', '0101000020E6100000373E2E23C6CA20C086A485BD8CAF4540', 'SRID=4326;POINT(-9.013628 42.561386)', 'fields-wd1-2026-09-26b-s010:e149d164-394f-4528-a19b-19dd92991b03:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 43.37148255372544, -8.396042918581868 -> 42.561386, -9.013628', '[{"source": "https://en.wikipedia.org/wiki/Castro_de_A_Cid%C3%A1", "url": "https://en.wikipedia.org/wiki/Castro_de_A_Cid%C3%A1", "quote": "42°33′41″N 9°00′49″W", "outcome": "found"}, {"source": "https://barbanzarousa.eu/concello/ribeira/castro-da-cida", "url": "https://barbanzarousa.eu/concello/ribeira/castro-da-cida", "quote": "42.561497020607, -9.013607716638", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia places the castro on the summit of Monte da Cidá between Artes and Carreira (Ribeira) at 42.561386, -9.013628 and the Barbanza-Arousa tourist board at 42.561497, -9.013608; the stored point lies 103 km away near A Coruña, so it is replaced.", "value_page": null}]'::jsonb),
