    ('e149d164-394f-4528-a19b-19dd92991b03'::uuid, 'site_type', 'City/town/settlement', 'Fort', 'fields-wd1-2026-09-26b-s010:e149d164-394f-4528-a19b-19dd92991b03:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Fort''', '[{"source": "https://vive.eixoatlantico.com/en/recurso/castro-da-cida/", "url": "https://vive.eixoatlantico.com/en/recurso/castro-da-cida/", "quote": "The Cida fort is an example of the first Celtic settlements in Ribeira.", "outcome": "found"}, {"source": "https://www.nosdiario.gal/articulo/cultura/castro-da-cida-ribeira/20210610223854123249.html", "url": "https://www.nosdiario.gal/articulo/cultura/castro-da-cida-ribeira/20210610223854123249.html", "quote": "O Castro da Cidá/Cidade é un recinto fortificado recentemente incorporado ao corpus de castros galegos", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "Eixo Atlántico calls the site the Cida fort and Nós Diario a fortified enclosure (castro) with walls; a walled Iron Age castro is a hillfort, so Fort is more specific than City/town/settlement.", "value_page": null}]'::jsonb),
    ('e1581c93-ce65-45e9-8d83-3392e9fc8a31'::uuid, 'geom', '0101000020E61000009845E1E37D7E334003F83271354D4640', 'SRID=4326;POINT(19.52361 44.58833)', 'fields-wd1-2026-09-26b-s010:e1581c93-ce65-45e9-8d83-3392e9fc8a31:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 44.60319342602454, 19.494108431337366 -> 44.58833, 19.52361', '[{"source": "https://en.wikipedia.org/wiki/Trojanov_Grad", "url": "https://en.wikipedia.org/wiki/Trojanov_Grad", "quote": "44.58833°N 19.52361°E", "outcome": "found"}, {"source": "https://podaci.com/srbija/lokacije/Trojanov-Grad.html", "url": "https://podaci.com/srbija/lokacije/Trojanov-Grad.html", "quote": "44.5885, 19.5239", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia places the Trojanov Grad fortress on Mount Cer at 44.58833, 19.52361, and the Podaci.com site guide gives the final on-foot waypoint to the fort''s tower at 44.5885, 19.5239, 0.02 km away. The stored point is 2.9 km off, at Cer''s main summit rather than the fort.", "value_page": null}]'::jsonb),
