    ('e1581c93-ce65-45e9-8d83-3392e9fc8a31'::uuid, 'period_name', '1 - 500 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s010:e1581c93-ce65-45e9-8d83-3392e9fc8a31:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e1581c93-ce65-45e9-8d83-3392e9fc8a31'::uuid, 'period_start', '1', '-1000', 'fields-wd1-2026-09-26b-s010:e1581c93-ce65-45e9-8d83-3392e9fc8a31:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''1'' -> ''-1000''', '[{"source": "https://d-nb.info/1378649753/34", "url": "https://d-nb.info/1378649753/34", "quote": "clear indicators of a substantial transformation in landscape use between approximately 1000 and 850 BCE", "outcome": "found"}, {"source": "https://doi.fil.bg.ac.rs/pdf/journals/arhe_apn/2025/arhe_apn-2025-21-4.pdf", "url": "https://doi.fil.bg.ac.rs/pdf/journals/arhe_apn/2025/arhe_apn-2025-21-4.pdf", "quote": "9th century BCE) on the western scarp, accompanied by a massive rubble rampart", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "MISSING", "reasoning": "The site''s first occupation is the prehistoric hillfort, not the late 3rd or early 4th century AD Roman fort. The Institute of Archaeology''s LiDAR paper dates Trojanov Grad''s Bosut-culture stone wall and ditch to the 10th-9th century BCE. The Open Geosciences paper counts Trojanov Grad among the Kalakaca-group hillforts of the Transitional period and dates their building to about 1000-850 BCE. So the start is c. 1000 BC, in the 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('e180ea7b-079b-44f8-88db-128ddc3ee492'::uuid, 'period_name', '4500 - 3000 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s010:e180ea7b-079b-44f8-88db-128ddc3ee492:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -5000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e180ea7b-079b-44f8-88db-128ddc3ee492'::uuid, 'period_start', '-4000', '-5000', 'fields-wd1-2026-09-26b-s010:e180ea7b-079b-44f8-88db-128ddc3ee492:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-4000'' -> ''-5000''', '[{"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2382", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2382", "quote": "The earliest human occupation on the hill goes back to the Neolithic period (about 5000 B.C.).", "outcome": "found"}, {"source": "https://www.greece-is.com/built-giants-archaeological-guide-tiryns/", "url": "https://www.greece-is.com/built-giants-archaeological-guide-tiryns/", "quote": "Inhabited since the Neolithic (“New Stone Age”), 7th-4th millennium BC,", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture (Odysseus) dates the earliest occupation of the Tiryns hill to the Neolithic, about 5000 BC, and Greece Is dates the Neolithic habitation to the 7th-4th millennium BC; the start therefore lies before 4500 BC, not in the stored 4500 - 3000 BC bucket, and the Ministry''s c. 5000 BC is taken.", "value_page": null}]'::jsonb),
    ('e1976732-579b-4f25-be81-626008526093'::uuid, 'site_type', 'Temple complex', 'Temple', 'fields-wd1-2026-09-26b-s010:e1976732-579b-4f25-be81-626008526093:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Temple complex'' -> ''Temple''', '[{"source": "https://www.greekdorictemples.com/assos-athena", "url": "https://www.greekdorictemples.com/assos-athena", "quote": "The Doric temple at Assos is the only one of its kind in Asia Minor.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Athenatempel_(Assos)", "url": "https://de.wikipedia.org/wiki/Athenatempel_(Assos)", "quote": "Der Athenatempel von Assos ist der einzige archaische Tempel dorischer Ordnung in Kleinasien", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the single archaic Doric temple of Athena on the Assos acropolis, not a complex of temples, so Temple is the specific type.", "value_page": null}]'::jsonb),
