    ('e1edddb2-56c8-498b-b926-78642bc312e2'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s010:e1edddb2-56c8-498b-b926-78642bc312e2:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
