    ('e2293ae0-0b9a-47cd-869e-971074072947'::uuid, 'source_url', 'https://www.lonelyplanet.com/tunisia/central-tunisia-1331880/attractions/kbor-klib/a/poi-sig/1599046/1331880', 'https://es.wikipedia.org/wiki/Kbor_klib', 'fields-wd1-2026-09-26b-s010:e2293ae0-0b9a-47cd-869e-971074072947:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://www.lonelyplanet.com/tunisia/central-tunisia-1331880/attractions/kbor-klib/a/poi-sig/1599046/1331880'' -> ''https://es.wikipedia.org/wiki/Kbor_klib''', '[{"source": "https://es.wikipedia.org/wiki/Kbor_klib", "url": "https://es.wikipedia.org/wiki/Kbor_klib", "quote": "Kbor Klib (la tumba de Klib) es un sitio arqueológico de Túnez, de origen desconocido, situado en la gobernación de Siliana, a unos 20 km al sur de Siliana.", "outcome": "found"}, {"source": "https://www.lonelyplanet.com/points-of-interest/kbor-klib/1599046", "url": "https://www.lonelyplanet.com/points-of-interest/kbor-klib/1599046", "quote": "Standing in a farmer''s field in remote central Tunisia, the mysterious ruined stone walls of Kbor Klib don''t look like much, but they''ve been intriguing researchers for years.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0139)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Lonely Planet URL is an old path that redirects; the site has its own Wikipedia article in Spanish (and Catalan), Kbor klib, which describes this archaeological site south of Siliana, as does Lonely Planet''s current page, so the Wikipedia article replaces the redirecting URL.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Kbor klib", "unreadable": false, "wikibase_item": "Q2837010"}}]'::jsonb),
    ('e282f2a0-5fbd-445b-81dc-63432936feff'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s010:e282f2a0-5fbd-445b-81dc-63432936feff:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e282f2a0-5fbd-445b-81dc-63432936feff'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s010:e282f2a0-5fbd-445b-81dc-63432936feff:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia only labels the paintings ''Neolithic'' and Archaeolist says they ''likely date back to the Neolithic era''; Vernet''s inventory describes the paintings (red antelopes, two chariots) without any date. No source dates the start of the site with a year, century or millennium.", "value_page": null}]'::jsonb),
    ('e2f7cf07-9034-4e60-82e1-b43f37fc91c1'::uuid, 'site_type', 'Earthwork', 'Military', 'fields-wd1-2026-09-26b-s010:e2f7cf07-9034-4e60-82e1-b43f37fc91c1:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Earthwork'' -> ''Military''', '[{"source": "https://en.wikipedia.org/wiki/Gei%C3%9Fkopf_(Central_Black_Forest)", "url": "https://en.wikipedia.org/wiki/Gei%C3%9Fkopf_(Central_Black_Forest)", "quote": "During the Migration Period there was evidently a Roman or Germanic military camp on the strategically placed heights.", "outcome": "found"}, {"source": "https://www.berghaupten.de/gemeinde--politik/infos-zur-gemeinde/geschichtliches/die-alamannen-auf-dem-geisskopf", "url": "https://www.berghaupten.de/gemeinde--politik/infos-zur-gemeinde/geschichtliches/die-alamannen-auf-dem-geisskopf", "quote": "Für den Geiskopf ergibt sich damit aus Sicht der Archäologen das Bild einer kriegerische geprägten Höhensiedlung, die eher als militärischer Stützpunkt denn als Fürstensitz zu deuten ist.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources interpret the site as a military camp or base of warriors (over 1,300 metal finds, many weapons and late Roman military belt fittings); Wikipedia states that no bank or ditch survives, so the stored Earthwork is wrong and Military fits.", "value_page": null}]'::jsonb),
    ('e2f8cf43-f499-4363-8fcb-af93e79ea756'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s010:e2f8cf43-f499-4363-8fcb-af93e79ea756:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Ancient_Corinth", "url": "https://en.wikipedia.org/wiki/Ancient_Corinth", "quote": "was a city-state (polis) on the Isthmus of Corinth, the narrow stretch of land that joins the Peloponnese peninsula to mainland Greece", "outcome": "found"}, {"source": "https://www.worldhistory.org/corinth/", "url": "https://www.worldhistory.org/corinth/", "quote": "Corinth was a Greek, Hellenistic and Roman city located on the isthmus which connects mainland Greece with the Peloponnese.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe Ancient Corinth as a city (a polis, a Greek, Hellenistic and Roman city), not as megalithic stones; the stored ''Megalithic stones'' has no support, so the type is City.", "value_page": null}]'::jsonb),
    ('e2fc0a30-cd29-473d-ad34-7e109b098cb7'::uuid, 'site_type', 'Monument', 'Funerary', 'fields-wd1-2026-09-26b-s010:e2fc0a30-cd29-473d-ad34-7e109b098cb7:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Monument'' -> ''Funerary''', '[{"source": "https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile", "url": "https://en.wikipedia.org/wiki/Funerary_naiskos_of_Demetria_and_Pamphile", "quote": "It is one of the last decorated funerary monuments that were placed in the ancient Kerameikos cemetery before the prohibition of decorated tombs in the late fourth century BC.", "outcome": "found"}, {"source": "https://topostext.org/place/380237XKer", "url": "https://topostext.org/place/380237XKer", "quote": "Some of the best-known funerary monuments are the Tomb of Dexileo, the Stele of Hegeso (c. 400 BC), the Relief of Demetria and Pamphile", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both Wikipedia and ToposText describe it as a funerary monument (a grave naiskos marking the sisters'' tomb) in the Kerameikos cemetery; Funerary is more specific than the generic Monument.", "value_page": null}]'::jsonb),
    ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s010:e3357e9e-c79f-43db-bfb5-7e62ba21daff:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -2500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'period_start', '-4500', '-2500', 'fields-wd1-2026-09-26b-s010:e3357e9e-c79f-43db-bfb5-7e62ba21daff:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-4500'' -> ''-2500''', '[{"source": "https://cornishancientsites.com/ancient-sites/chapel-carn-brea/", "url": "https://cornishancientsites.com/ancient-sites/chapel-carn-brea/", "quote": "The second is the summit cairn (SW 3859 2807) [pictured right] which is a Late Neolithic/early Bronze Age entrance grave, (c.2500 BC)", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "quote": "ENTRANCE GRAVE (Late Neolithic - 3000 BC to 2351 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "MISSING", "reasoning": "The Cornish Ancient Sites Protection Network dates the summit entrance grave to c. 2500 BC and the National Trust heritage record dates it to the Late Neolithic, 3000 to 2351 BC; the start therefore lies in the 3000 - 1500 BC bucket, not 4500 - 3000 BC.", "value_page": null}]'::jsonb),
    ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'site_type', 'Barrow', 'Cairn', 'fields-wd1-2026-09-26b-s010:e3357e9e-c79f-43db-bfb5-7e62ba21daff:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Barrow'' -> ''Cairn''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "quote": "Chapel Carn Brae cairn is interpreted as a multiphase cairn which appears to have originated as an entrance grave", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=10213", "url": "https://www.megalithic.co.uk/article.php?sid=10213", "quote": "Alternative Name: Chapel Carn Brea Summit Chambered Cairn", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "CONFLICT", "reasoning": "The National Trust record and the Megalithic Portal describe the site as a multiphase stone cairn over a chambered entrance grave; Cairn is more specific than Barrow for this stone-built mound.", "value_page": null}]'::jsonb),
    ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Chapel_Carn_Brea', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669', 'fields-wd1-2026-09-26b-s010:e3357e9e-c79f-43db-bfb5-7e62ba21daff:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Chapel_Carn_Brea'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102669", "quote": "Chapel Carn Brea Cairn, St Just Sites Record ID: 91360 / MNA102669", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=10213", "url": "https://www.megalithic.co.uk/article.php?sid=10213", "quote": "Site Name: Chapel Carn Brea Tomb Alternative Name: Chapel Carn Brea Summit Chambered Cairn", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill; the National Trust heritage record, from the owner of the site, is the monument record of the Chapel Carn Brea summit cairn itself and loads as plain HTML.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('e3cf8ea1-6146-400c-a642-6f855dd88031'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s010:e3cf8ea1-6146-400c-a642-6f855dd88031:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e3cf8ea1-6146-400c-a642-6f855dd88031'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s010:e3cf8ea1-6146-400c-a642-6f855dd88031:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "clear", "status": "MISSING", "reasoning": "The stored -500 is wrong: Wikipedia reports Middle Palaeolithic occupation, the 1964 report Middle Stone Age tools in Pleistocene deposits, and the Department of Archaeology and Museums a chronology from 18,000 BCE; apart from that one register entry the sources give only periods or BP/years-ago ages, so no two independent sources state a start year and the field is emptied.", "value_page": null}]'::jsonb),
    ('e3f62da6-9fdb-4011-9135-47f41c546ac7'::uuid, 'period_name', '4500 - 3000 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s010:e3f62da6-9fdb-4011-9135-47f41c546ac7:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -1500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e3f62da6-9fdb-4011-9135-47f41c546ac7'::uuid, 'period_start', '-4500', '-1500', 'fields-wd1-2026-09-26b-s010:e3f62da6-9fdb-4011-9135-47f41c546ac7:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-4500'' -> ''-1500''', '[{"source": "https://sardegnaversounesco.org/en/the-nuragic-sanctuary-of-romanzesu/", "url": "https://sardegnaversounesco.org/en/the-nuragic-sanctuary-of-romanzesu/", "quote": "The birth of the settlement, dating back to the Middle Bronze Age (1500 BC), was favored by an abundant spring", "outcome": "found"}, {"source": "https://roadtripsandsuitcases.com/sardinia-nuragic-complex-romanzesu/", "url": "https://roadtripsandsuitcases.com/sardinia-nuragic-complex-romanzesu/", "quote": "The site itself is generally associated with the Bronze Age and is often dated as far back as the 14th century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator Maria Ausilia Fadda (quoted from Archeologia Viva 2017) dates the birth of the settlement to the Middle Bronze Age, 1500 BC, and other sources date the Nuragic village to the 14th century BC (the regional portal puts the first huts in the advanced Middle Bronze Age); the start lies in the 1500 - 500 BC bucket, not the stored -4500 (4500 - 3000 BC), so the value becomes -1500.", "value_page": null}]'::jsonb),
    ('e3f62da6-9fdb-4011-9135-47f41c546ac7'::uuid, 'site_type', 'City/town/settlement', 'Sanctuary', 'fields-wd1-2026-09-26b-s010:e3f62da6-9fdb-4011-9135-47f41c546ac7:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Sanctuary''', '[{"source": "https://en.wikipedia.org/wiki/Su_Romanzesu", "url": "https://en.wikipedia.org/wiki/Su_Romanzesu", "quote": "It consists of a Bronze Age nuragic sanctuary village of more than seven hectares.", "outcome": "found"}, {"source": "https://www.sardegnaturismo.it/en/explore/romanzesu", "url": "https://www.sardegnaturismo.it/en/explore/romanzesu", "quote": "The village-sanctuary of Romanzesu stands on a plateau in the locality of", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Sardinian tourism portal describe Romanzesu as a Nuragic sanctuary village (village-sanctuary) whose defining remains are a well temple with a stepped amphitheatre, megaron temples, a heroon and a labyrinthine ceremonial enclosure; Sanctuary is more specific for it than the generic City/town/settlement.", "value_page": null}]'::jsonb),
    ('e406449f-9274-4ab6-ba10-0d4ea77fa7af'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s010:e406449f-9274-4ab6-ba10-0d4ea77fa7af:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e406449f-9274-4ab6-ba10-0d4ea77fa7af'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s010:e406449f-9274-4ab6-ba10-0d4ea77fa7af:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Megalithic Portal, the Somerset HER text (via Digital Digging) and the Somerset Wildlife Trust all call King''s Castle Iron Age without giving a year or century, and Wikipedia notes it has never been excavated; the only dated statement is Wikipedia''s generic remark that hill forts arose around the start of the first millennium BC. No two sources date this site''s start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('e406449f-9274-4ab6-ba10-0d4ea77fa7af'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s010:e406449f-9274-4ab6-ba10-0d4ea77fa7af:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/King%27s_Castle,_Wells", "url": "https://en.wikipedia.org/wiki/King%27s_Castle,_Wells", "quote": "King''s Castle is an Iron Age enclosed hilltop settlement at the south-western edge of the Mendip Hills near Wells in Somerset, England.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=34801", "url": "https://www.megalithic.co.uk/article.php?sid=34801", "quote": "It is a small fortified settlement thought to be for only one family.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls King''s Castle an Iron Age enclosed hilltop settlement and the Megalithic Portal a small fortified settlement for perhaps one family (its scheduled name is ''Iron Age defended settlement''); it is a small defended enclosure, not a town, so Settlement fits better than City/town/settlement.", "value_page": null}]'::jsonb),
    ('e4631001-b923-4f36-be7f-c961f9e287ba'::uuid, 'geom', '0101000020E61000001FC8B7E51023394011EDCFE85BAB4140', 'SRID=4326;POINT(25.163373 35.297953)', 'fields-wd1-2026-09-26b-s010:e4631001-b923-4f36-be7f-c961f9e287ba:geom', 'fields-wd1-2026-09-26b-s010 (wd1-point): 35.33874235298766, 25.13697658287867 -> 35.297953, 25.163373', '[{"source": "https://www.megalithic.co.uk/article.php?sid=10024", "url": "https://www.megalithic.co.uk/article.php?sid=10024", "quote": "Latitude: 35.297953N  Longitude: 25.163373E", "outcome": "found"}, {"source": "https://topostext.org/place/353252PKno", "url": "https://topostext.org/place/353252PKno", "quote": "Latitude: 35.297800 Longitude: 25.163100", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Knossos", "url": "https://en.wikipedia.org/wiki/Knossos", "quote": "35°17′53″N 25°9′47″E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Prince of the Lilies is a relief fresco excavated in the southern part of the palace of Knossos (a copy stands there today); the stored point lies about 4.5 km away at the Heraklion Archaeological Museum, which keeps the original. The Megalithic Portal, ToposText and Wikipedia place the Knossos palace at about 35.298, 25.163.", "value_page": null}]'::jsonb),
