    ('e4631001-b923-4f36-be7f-c961f9e287ba'::uuid, 'site_type', 'Rock art', NULL, 'fields-wd1-2026-09-26b-s010:e4631001-b923-4f36-be7f-c961f9e287ba:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''Rock art'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "clear", "status": "CONFLICT", "reasoning": "The sources describe the entry as a Minoan relief fresco (painted stucco) from a palace wall, which is not rock art and matches none of the canonical site types; no two sources describe it as a kind of site, so the field is emptied.", "value_page": null}]'::jsonb),
