    ('e473f682-8b9c-4d5c-b2cc-0ca24fcc06bc'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s010:e473f682-8b9c-4d5c-b2cc-0ca24fcc06bc:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "Only digitaldigging.net states a date for this site (ApSimon ''dated the occupation layer to the 1st century BCE'', which contradicts the stored 1500 - 500 BC bucket); Wikipedia gives only the general start of hillforts and the excavator''s scanned note is not readable text, so there are not two independent dated sources.", "value_page": null}]'::jsonb),
    ('e48a661d-c148-4a0f-abff-f862d61524b7'::uuid, 'period_name', '500 - 1000 AD', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s010:e48a661d-c148-4a0f-abff-f862d61524b7:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start 1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1000) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e48a661d-c148-4a0f-abff-f862d61524b7'::uuid, 'period_start', '500', '1000', 'fields-wd1-2026-09-26b-s010:e48a661d-c148-4a0f-abff-f862d61524b7:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''500'' -> ''1000''', '[{"source": "https://es.wikipedia.org/wiki/T%C3%BAcume", "url": "https://es.wikipedia.org/wiki/T%C3%BAcume", "quote": "La fundación de la ciudad, entre los años 1000 y 1100, coincide con la caída del anterior centro sicán, Batán Grande, a orillas del río La Leche, que fue quemada y abandonada en esa época.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=43230", "url": "https://www.megalithic.co.uk/article.php?sid=43230", "quote": "A town of the Lambayeque/Sicán culture covering 540 acres dating from around 1000 CE with later Chimú and Inca additions.", "outcome": "found"}, {"source": "https://www.kon-tiki.no/en/heyerdahls-expeditions/tucume", "url": "https://www.kon-tiki.no/en/heyerdahls-expeditions/tucume", "quote": "The investigations determined that the pyramids were first constructed in 1100 AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "replace", "status": "MISSING", "reasoning": "Spanish Wikipedia puts the founding between 1000 and 1100, the Megalithic Portal dates the town from around 1000 CE, and the Kon-Tiki Museum (home of Heyerdahl''s excavation project) says the pyramids were first built in 1100 AD. All three fall in the 1000-1500 AD bucket, not in the stored 500-1000 bucket. English Wikipedia''s ''c. 800'' is an outlier.", "value_page": null}]'::jsonb),
    ('e4af0fdf-eef8-4b9f-ae5b-3e9329df9904'::uuid, 'source_url', 'https://archaeologyworldnews.com/4750-year-old-megalithic-stone-plaza-discovered-in-the-high-andes-of-peru/?fbclid=IwAR2yt1ae77jpf2DKFjD3uFIEOevixJVPRK4mZdLS5PwMwFdh-QXZ6iGvmDg', 'https://www.uwyo.edu/news/2024/02/uw-anthropologists-research-unveils-early-stone-plaza-in-the-andes.html', 'fields-wd1-2026-09-26b-s010:e4af0fdf-eef8-4b9f-ae5b-3e9329df9904:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://archaeologyworldnews.com/4750-year-old-megalithic-stone-plaza-discovered-in-the-high-andes-of-peru/?fbclid=IwAR2yt1ae77jpf2DKFjD3uFIEOevixJVPRK4mZdLS5PwMwFdh-QXZ6iGvmDg'' -> ''https://www.uwyo.edu/news/2024/02/uw-anthropologists-research-unveils-early-stone-plaza-in-the-andes.html''', '[{"source": "https://www.uwyo.edu/news/2024/02/uw-anthropologists-research-unveils-early-stone-plaza-in-the-andes.html", "url": "https://www.uwyo.edu/news/2024/02/uw-anthropologists-research-unveils-early-stone-plaza-in-the-andes.html", "quote": "Located at the Callacpuma archaeological site in the Cajamarca Basin of northern Peru, the plaza is built with large, vertically placed megalithic stones", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=60338", "url": "https://www.megalithic.co.uk/article.php?sid=60338", "quote": "Callacpuma Stone Circle Peru", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored news URL now redirects to a parked domain; the University of Wyoming''s release on its excavators'' study is a plain-HTML page about this very megalithic plaza at Callacpuma, which the Megalithic Portal also describes (the Science Advances page itself refuses automated requests).", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('e578e7e9-a9ec-48d0-9f9f-64f3f1b64a5e'::uuid, 'site_type', 'Ruin', 'Archaeological site', 'fields-wd1-2026-09-26b-s010:e578e7e9-a9ec-48d0-9f9f-64f3f1b64a5e:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Ruin'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Roman_fish_salting_factory", "url": "https://en.wikipedia.org/wiki/Roman_fish_salting_factory", "quote": "A site of archaeological and historical interest, it was declared a Bien de Interés Cultural site on 27 June 2002.", "outcome": "found"}, {"source": "https://www.algeciras.es/es/temas/cultura-y-ocio/delegacion-de-cultura/yacimiento-factoria-romana-san-nicolas/", "url": "https://www.algeciras.es/es/temas/cultura-y-ocio/delegacion-de-cultura/yacimiento-factoria-romana-san-nicolas/", "quote": "Las excavaciones arqueológicas en esta parcela han descubierto tres fábricas dedicadas a la elaboración de conservas de pescado y carne situadas en el corazón del barrio industrial de la antigua ciudad romana de Algeciras", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0133)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the excavated Roman fish-salting factory complex of Iulia Traducta; no canonical type names a production facility (the check wants the word ''infrastructure'', which no source uses), so the generic type applies. Wikipedia calls it a site of archaeological interest and the city of Algeciras describes the archaeological excavations that uncovered its three factories; Archaeological site describes it better than the stored Ruin, which no independent source uses.", "value_page": null}]'::jsonb),
    ('e5948e02-efb2-4c4e-b3e6-8295aa3cdcac'::uuid, 'site_type', 'Necropolis/tombs complex', 'Tomb', 'fields-wd1-2026-09-26b-s010:e5948e02-efb2-4c4e-b3e6-8295aa3cdcac:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Necropolis/tombs complex'' -> ''Tomb''', '[{"source": "https://www.phrygianmonuments.com/kumbet/", "url": "https://www.phrygianmonuments.com/kumbet/", "quote": "It is a rock tomb originally built in the Phrygian period.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/K%C3%BCmbet,_Seyitgazi", "url": "https://en.wikipedia.org/wiki/K%C3%BCmbet,_Seyitgazi", "quote": "the rock-cut tomb of Solon (Lion''s Temple)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "MISSING", "reasoning": "Aslanlı Mabet is a single rock-cut tomb (Solon''s Tomb) at Kümbet, not a necropolis or tomb complex; both sources describe it as one rock tomb, so Tomb is the specific type.", "value_page": null}]'::jsonb),
    ('e5948e02-efb2-4c4e-b3e6-8295aa3cdcac'::uuid, 'source_url', 'https://eskisehir.ktb.gov.tr/TR-157674/solonun-mezariaslanli-mabet.html', 'https://eskisehir.ktb.gov.tr/TR-336939/solonun-mezari---aslanli-mabet-seyitgazi.html', 'fields-wd1-2026-09-26b-s010:e5948e02-efb2-4c4e-b3e6-8295aa3cdcac:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://eskisehir.ktb.gov.tr/TR-157674/solonun-mezariaslanli-mabet.html'' -> ''https://eskisehir.ktb.gov.tr/TR-336939/solonun-mezari---aslanli-mabet-seyitgazi.html''', '[{"source": "https://eskisehir.ktb.gov.tr/TR-336939/solonun-mezari---aslanli-mabet-seyitgazi.html", "url": "https://eskisehir.ktb.gov.tr/TR-336939/solonun-mezari---aslanli-mabet-seyitgazi.html", "quote": "Aslan kabartmaları nedeniyle Aslanlı Mabet olarak da bilinir.", "outcome": "found"}, {"source": "https://www.phrygianmonuments.com/kumbet/", "url": "https://www.phrygianmonuments.com/kumbet/", "quote": "It is referred to as Solon’s Tomb on account of the name “Solon” read in the inscription inside the tomb.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Eskişehir directorate URL now redirects to the directorate''s home page; the directorate''s current page for ''Solon’un Mezarı - Aslanlı Mabet (Seyitgazi)'' is about this very tomb, and Phrygian Monuments independently names it Solon''s Tomb.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('e5bb0a42-df89-47d8-9ac4-669df257592a'::uuid, 'site_type', 'City/town/settlement', 'Village', 'fields-wd1-2026-09-26b-s010:e5bb0a42-df89-47d8-9ac4-669df257592a:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Village''', '[{"source": "https://www.sardegnaturismo.it/en/explore/nuragic-village-tiscali", "url": "https://www.sardegnaturismo.it/en/explore/nuragic-village-tiscali", "quote": "The Nuragic village of Tiscali, built along the walls of the depression and invisible until you get to the inside of the cavity", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6336323", "url": "https://www.megalithic.co.uk/article.php?sid=6336323", "quote": "Type: Ancient Village or Settlement", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Sardinian tourism portal and the Megalithic Portal describe Tiscali as a Nuragic village of some seventy huts inside the doline; Village is the most specific type that holds, narrower than City/town/settlement.", "value_page": null}]'::jsonb),
