    ('e6eab365-fb0c-4851-94f9-8fcc35f1238d'::uuid, 'period_start', '-4000', '-5655', 'fields-wd1-2026-09-26b-s010:e6eab365-fb0c-4851-94f9-8fcc35f1238d:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-4000'' -> ''-5655''', '[{"source": "https://www.exploreyourdna.com/site/ukraine/mamai-gora", "url": "https://www.exploreyourdna.com/site/ukraine/mamai-gora", "quote": "5 ancient DNA individuals excavated at Mamai-Gora, Ukraine, dated between 5655 BC and 270 BC.", "outcome": "found"}, {"source": "https://zenodo.org/records/10236204", "url": "https://zenodo.org/records/10236204", "quote": "The complex is preliminary dated back tp 6 millenia BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0151)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient-DNA site record for Mamai-Gora lists radiocarbon-dated individuals from 5655 BC (a Meso/Neolithic burial, Allentoft et al. 2024) to 270 BC, and the Zaporizhzhia University team''s dataset dates the Neolithic burial complex of about 100 graves found in 2020 preliminarily to the 6th millennium BC; the site''s first burials are therefore Neolithic, before 4500 BC, so the stored -4000 is replaced by -5655.", "value_page": null}]'::jsonb),
    ('e6eab365-fb0c-4851-94f9-8fcc35f1238d'::uuid, 'site_type', 'Mound/tumulus', 'Cemetery', 'fields-wd1-2026-09-26b-s010:e6eab365-fb0c-4851-94f9-8fcc35f1238d:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Mound/tumulus'' -> ''Cemetery''', '[{"source": "https://en.wikipedia.org/wiki/Monuments_of_national_significance_in_Zaporizhzhia_Oblast", "url": "https://en.wikipedia.org/wiki/Monuments_of_national_significance_in_Zaporizhzhia_Oblast", "quote": "Kurgan cemetery \"Mamai-mohyla\"", "outcome": "found"}, {"source": "https://we.org.ua/history/mogylnyk-mamaj-gora/", "url": "https://we.org.ua/history/mogylnyk-mamaj-gora/", "quote": "знаходиться один із найбільших у степовому Причорномор’ї курганний могильник", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0151)", "decision": "replace", "status": "CONFLICT", "reasoning": "The heritage register list names the site a kurgan cemetery (Mamai-mohyla) and the Pro Ukrainu account calls it one of the largest kurgan burial grounds (kurhannyi mohylnyk) of the steppe Black Sea region, a grave field with more than 600 burials rather than a single mound.", "value_page": null}]'::jsonb),
