    ('e765ff49-b186-4cf0-b32a-94a3aa453de9'::uuid, 'site_type', 'Museum', 'Religious', 'fields-wd1-2026-09-26b-s010:e765ff49-b186-4cf0-b32a-94a3aa453de9:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Museum'' -> ''Religious''', '[{"source": "https://archive.org/details/oapen-20.500.12657-57155", "url": "https://archive.org/details/oapen-20.500.12657-57155", "quote": "they examine the significance of Fiskerton as a religious site", "outcome": "found"}, {"source": "https://www.lincolnmuseum.com/exhibitions-and-events/view/the-fiskerton-causeway", "url": "https://www.lincolnmuseum.com/exhibitions-and-events/view/the-fiskerton-causeway", "quote": "was a site of immense importance in the Iron Age as it was a place of votive deposition - where objects were placed into the waters of the river as religious offerings.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "The find site is an Iron Age timber causeway where weapons, tools and the deliberately sunk log boats were deposited as offerings; the excavation monograph calls Fiskerton a religious site and the Lincoln Museum a place of votive deposition for religious offerings. The museum that now shows the boat is not the site, so Museum is replaced.", "value_page": null}]'::jsonb),
