    ('e7696c02-7c52-4ffb-8307-ed2694d0f3f3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/A%27ali', 'https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,19542,en.php', 'fields-wd1-2026-09-26b-s010:e7696c02-7c52-4ffb-8307-ed2694d0f3f3:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/A%27ali'' -> ''https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,19542,en.php''', '[{"source": "https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,19542,en.php", "url": "https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,19542,en.php", "quote": "A´ali East is one of the components of the UNESCO World Heritage Site, “Dilmun Burial Mounds”. It is the largest of all the Dilmun cemeteries of Bahrain both in dimensions and number of burial mounds.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23921", "url": "https://www.megalithic.co.uk/article.php?sid=23921", "quote": "The Giant Burial Mounds of A''ali are located around and inside A''ali village", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the town of A''ali; the Bahrain Authority for Culture and Antiquities'' page on the A''ali East Burial Mound Field (with the royal cemetery in its northern part) is the official page about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
