    ('e7c2dc58-a477-41c6-ad83-02fea34c8d56'::uuid, 'period_start', '-500', '-700', 'fields-wd1-2026-09-26b-s010:e7c2dc58-a477-41c6-ad83-02fea34c8d56:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-500'' -> ''-700''', '[{"source": "https://oedipusculturalroute.gr/en/points_of_interest/iero-irakleoys-pyra-oitis/", "url": "https://oedipusculturalroute.gr/en/points_of_interest/iero-irakleoys-pyra-oitis/", "quote": "Clay and metal offerings, spearheads, two bronze statuettes of the 6th or 7th century B.C. depicting a naked Heracles, 13 coins, and three partial inscriptions, indicate that festivals were held in honour of the hero in this specific area.", "outcome": "found"}, {"source": "https://camws.org/meeting/2005/abstracts2005/shaw.html", "url": "https://camws.org/meeting/2005/abstracts2005/shaw.html", "quote": "The Deltion article of 1919 to which Nilsson refers contains photographs of two figurines and of pottery inscribed with Heracles'' name, the latter being dated by the excavators to the seventh century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest finds at the cult place - bronze statuettes of the 7th/6th century BC and pottery inscribed with Heracles'' name that the excavators dated to the seventh century - put the start of the sanctuary in the 7th century BC, before the 3rd-century BC temple; -700 lies in the 1500 - 500 BC bucket, not the stored 500 BC - 1 AD one.", "value_page": null}]'::jsonb),
    ('e7e75467-cc43-437e-9221-5ed85c050e63'::uuid, 'period_name', '1500 - 500 BC', '1 - 500 AD', 'fields-wd1-2026-09-26b-s010:e7e75467-cc43-437e-9221-5ed85c050e63:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start 301 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(301) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e7e75467-cc43-437e-9221-5ed85c050e63'::uuid, 'period_start', '-800', '301', 'fields-wd1-2026-09-26b-s010:e7e75467-cc43-437e-9221-5ed85c050e63:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-800'' -> ''301''', '[{"source": "https://origenesdeeuropa.eu/lugar_patrimonio/archaeological-site-of-zaldapa/", "url": "https://origenesdeeuropa.eu/lugar_patrimonio/archaeological-site-of-zaldapa/", "quote": "in the early 4th century, probably under Emperor Constantine I the Great. It is protected by a powerful fortress wall with 32 towers and 3 gates.", "outcome": "found"}, {"source": "https://www.krushari.bg/bg/802-%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82-%D0%B7%D0%B0%D0%BB%D0%B4%D0%B0%D0%BF%D0%B0", "url": "https://www.krushari.bg/bg/802-%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82-%D0%B7%D0%B0%D0%BB%D0%B4%D0%B0%D0%BF%D0%B0", "quote": "Изградена през втората половина на ІV в., крепостта функционира около 250 години", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "MISSING", "reasoning": "The Origins of Europe heritage entry says the Zaldapa fortress was built from its foundations (a fundamentis) in the early 4th century, and Krushari municipality dates its construction to the 4th century; the 8th-century-BC Thracian settlement rests on a single news site (Archaeology in Bulgaria) echoed by Wikipedia, so the securely attested start is the 4th century AD (301), not the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('e7e75467-cc43-437e-9221-5ed85c050e63'::uuid, 'site_type', 'Fortress/citadel', 'City', 'fields-wd1-2026-09-26b-s010:e7e75467-cc43-437e-9221-5ed85c050e63:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Zaldapa", "url": "https://en.wikipedia.org/wiki/Zaldapa", "quote": "was a large Late Roman fortified city", "outcome": "found"}, {"source": "https://origenesdeeuropa.eu/lugar_patrimonio/archaeological-site-of-zaldapa/", "url": "https://origenesdeeuropa.eu/lugar_patrimonio/archaeological-site-of-zaldapa/", "quote": "Zaldapa is the largest fortified Roman-Byzantine town in the interior of the Roman province of Scythia (Dobrudzha).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "CONFLICT", "reasoning": "Zaldapa was a walled Late Roman city - a bishopric listed among the towns of Scythia, over 35 ha with basilicas and a reservoir - which Wikipedia calls a large fortified city and the Origins of Europe entry the largest fortified Roman-Byzantine town of Scythia; City is more specific than Fortress/citadel.", "value_page": null}]'::jsonb),
