    ('e8740838-159b-4b95-9954-a3f96b68c2c9'::uuid, 'source_url', 'https://www.gidilmeli.com/Helenistik-mabet-kas/11839/1', 'https://kulturenvanteri.com/en/yer/antiphellos-helenistik-mabet/', 'fields-wd1-2026-09-26b-s010:e8740838-159b-4b95-9954-a3f96b68c2c9:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://www.gidilmeli.com/Helenistik-mabet-kas/11839/1'' -> ''https://kulturenvanteri.com/en/yer/antiphellos-helenistik-mabet/''', '[{"source": "https://kulturenvanteri.com/en/yer/antiphellos-helenistik-mabet/", "url": "https://kulturenvanteri.com/en/yer/antiphellos-helenistik-mabet/", "quote": "Antiphellos Helenistik Mabet", "outcome": "found"}, {"source": "https://www.antalyakulturenvanteri.com/helenistik-mabet/", "url": "https://www.antalyakulturenvanteri.com/helenistik-mabet/", "quote": "Helenistik Mabet; Antalya ili, Kaş ilçesi sınırları içerisinde, Antiphellos Antik Kenti’nin batısında, günümüzde Kaş ilçe merkezinde yer alan, MÖ 3-1. yüzyıllar arasında Helenistik Dönem’de inşa edilmiş bir tapınak yapısıdır.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored gidilmeli.com page is dead (HTTP 404). The temple has no Wikipedia article of its own; the Kültür Envanteri entry ''Antiphellos Helenistik Mabet'' (type Temple, Kaş) is about this very monument, and the Antalya cultural inventory names the same Helenistik Mabet in Kaş.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
