    ('e8a07988-7219-449d-8cd1-612761502bfd'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s010:e8a07988-7219-449d-8cd1-612761502bfd:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0149)", "decision": "clear", "status": "MISSING", "reasoning": "The sources give only relative ages (''1150 to 2000 years old'', Archaic designs ''2,000-3,000 years ago'') or a period of heaviest use (Tanque Verde, A.D. 1150-1300) and the NRHP''s generic significance bands; no two sources state a year or century for the start of the site.", "value_page": null}]'::jsonb),
    ('e8a07988-7219-449d-8cd1-612761502bfd'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Cocoraque_Butte_Archaeological_District', 'https://npgallery.nps.gov/AssetDetail/NRIS/75000355', 'fields-wd1-2026-09-26b-s010:e8a07988-7219-449d-8cd1-612761502bfd:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Cocoraque_Butte_Archaeological_District'' -> ''https://npgallery.nps.gov/AssetDetail/NRIS/75000355''', '[{"source": "https://npgallery.nps.gov/AssetDetail/NRIS/75000355", "url": "https://npgallery.nps.gov/AssetDetail/NRIS/75000355", "quote": "Cocoraque Butte Archeological District", "outcome": "found"}, {"source": "https://www.blm.gov/visit/ironwood", "url": "https://www.blm.gov/visit/ironwood", "quote": "the Cocoraque Butte Archaeological District, are listed on the National Register of Historic Places.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia URL is only a redirect into a section of the Ironwood Forest National Monument article, which is about the monument; the National Park Service''s National Register record (NRIS 75000355) is a page about this very district, and the Bureau of Land Management independently names it as one of the monument''s three listed properties.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('e8acbde6-7c73-409f-a4cb-6bb47736f4c7'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s010:e8acbde6-7c73-409f-a4cb-6bb47736f4c7:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e8acbde6-7c73-409f-a4cb-6bb47736f4c7'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s010:e8acbde6-7c73-409f-a4cb-6bb47736f4c7:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "clear", "status": "MISSING", "reasoning": "Only English Wikipedia (and its copies) says the area was inhabited since the third millennium BC because of menhirs found nearby (at Algund), and that the city proper began in 15 BC with the road station Statio Maiensis; German Wikipedia names La Tène finds and a first mention in 857. No second independent source dates the start of Merano, so -3000 is emptied.", "value_page": null}]'::jsonb),
    ('e8acbde6-7c73-409f-a4cb-6bb47736f4c7'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s010:e8acbde6-7c73-409f-a4cb-6bb47736f4c7:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Merano", "url": "https://en.wikipedia.org/wiki/Merano", "quote": "The Counts at Castle Tyrol elevated Merano to the status of a city during the 13th century", "outcome": "found"}, {"source": "https://www.treccani.it/enciclopedia/merano_(Enciclopedia-Italiana)/", "url": "https://www.treccani.it/enciclopedia/merano_(Enciclopedia-Italiana)/", "quote": "Città della reġione altoatesina (prov. di Bolzano) sulla grande conoide formata dal fiume Passirio al suo sbocco nell''Adige.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0015)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia says Merano was raised to the status of a city in the 13th century and the Enciclopedia Italiana (Treccani) defines Merano as a ''Città'' of the Alto Adige region on the Passirio fan; the entry is the town itself, a city and comune, not a megalithic monument, although its prehistoric menhirs are mentioned in its history.", "value_page": null}]'::jsonb),
    ('e8bb0905-e8ca-441d-a35b-041af4645ffb'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s010:e8bb0905-e8ca-441d-a35b-041af4645ffb:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e8bb0905-e8ca-441d-a35b-041af4645ffb'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s010:e8bb0905-e8ca-441d-a35b-041af4645ffb:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "clear", "status": "MISSING", "reasoning": "The parish''s remains run from Bronze Age cairns to Iron Age grave fields and runestones, and no page gives a year, century or millennium for the start of this record as one site; the stored -4500 (Neolithic bucket) is unsupported.", "value_page": null}]'::jsonb),
    ('e8bb0905-e8ca-441d-a35b-041af4645ffb'::uuid, 'site_type', 'Mound/tumulus', NULL, 'fields-wd1-2026-09-26b-s010:e8bb0905-e8ca-441d-a35b-041af4645ffb:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''Mound/tumulus'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "clear", "status": "CONFLICT", "reasoning": "The sources describe the parish as holding many kinds of remains (gravrösen, gravfält, a storhög, fornborgar, runristningar), so no single type holds for the record; one great mound among them does not make the parish a Mound/tumulus.", "value_page": null}]'::jsonb),
    ('e8bb0905-e8ca-441d-a35b-041af4645ffb'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Sollentuna_socken', NULL, 'fields-wd1-2026-09-26b-s010:e8bb0905-e8ca-441d-a35b-041af4645ffb:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''https://en.wikipedia.org/wiki/Sollentuna_socken'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the administrative parish (socken) of Sollentuna, i.e. the region, not an ancient site; no page about one monument that this record stands for can be named.", "value_page": null}]'::jsonb),
