    ('e8bc112c-9e95-4728-b181-e78d7de1fa26'::uuid, 'site_type', 'Fortress/citadel', 'Palace', 'fields-wd1-2026-09-26b-s010:e8bc112c-9e95-4728-b181-e78d7de1fa26:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Palace''', '[{"source": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "url": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "quote": "The Wolseong Belt is based around the site of the former palace", "outcome": "found"}, {"source": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000160000000&sCcebCtcd=37", "url": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000160000000&sCcebCtcd=37", "quote": "Wolseong is the capital fortress where the royal palace of Silla was once located.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "MISSING", "reasoning": "The belt is the Silla royal palace precinct: Wikipedia describes it as based around the former palace Wolseong, the national register (listed as Wolseong Palace Site) calls Wolseong the fortress of the royal palace, and the belt also holds the Anapji pond on the site of a second palace. Palace is the most specific type for that; Fortress/citadel only names the palace''s enclosing wall.", "value_page": null}]'::jsonb),
    ('e8bc112c-9e95-4728-b181-e78d7de1fa26'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas', 'https://en.wikipedia.org/wiki/Wolseong', 'fields-wd1-2026-09-26b-s010:e8bc112c-9e95-4728-b181-e78d7de1fa26:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas'' -> ''https://en.wikipedia.org/wiki/Wolseong''', '[{"source": "https://en.wikipedia.org/wiki/Wolseong", "url": "https://en.wikipedia.org/wiki/Wolseong", "quote": "Originally the ice storehouse was in the west of Wolseong but has been moved to its present location near the northern castle turret.", "outcome": "found"}, {"source": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000160000000&sCcebCtcd=37", "url": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000160000000&sCcebCtcd=37", "quote": "Wolseong is the capital fortress where the royal palace of Silla was once located.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the whole World Heritage property (Q495241). The belt has no article of its own and is based around the palace site of Wolseong, so the English Wikipedia article on Wolseong is the page about this site; the Korea Heritage Service register describes the same palace site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Wolseong", "unreadable": false, "wikibase_item": "Q471292"}}]'::jsonb),
    ('e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s010:e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s010:e8d4bfaa-7f9f-440a-9fc9-7e5bb12f5e6e:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "clear", "status": "MISSING", "reasoning": "The site''s earliest attested history is a Romano-British settlement with a Roman well found during quarrying. The quarry itself only opened in 1916. Only Wikipedia (through Hagen''s 1971 paper ''A second century Roman well near Leighton Buzzard'') puts a century on it, and the Bedfordshire Archives page says only ''Romano-British period'', so no two sources date the start with a year or century. The stored 500 BC - 1 AD bucket is not supported.", "value_page": null}]'::jsonb),
