    ('e8e302a0-70b2-4346-ac75-340a4d6499a2'::uuid, 'period_start', '-2000', '-5000', 'fields-wd1-2026-09-26b-s010:e8e302a0-70b2-4346-ac75-340a4d6499a2:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-2000'' -> ''-5000''', '[{"source": "http://www.aspel.gr/argos.html", "url": "http://www.aspel.gr/argos.html", "quote": "The earliest evidence of human habitation is a Neolithic settlement at the foot of Aspis hill which dates to around 5000 BC making Argos one of the oldest continually inhabited cities in the world.", "outcome": "found"}, {"source": "https://www.worldatlas.com/cities/the-oldest-cities-in-europe-55266.html", "url": "https://www.worldatlas.com/cities/the-oldest-cities-in-europe-55266.html", "quote": "Argos (with archaeological evidence from the 5th millennium BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "MISSING", "reasoning": "The Archaeological Sites of Argolis guide dates the first settlement of Argos, at the foot of the Aspis hill, to around 5000 BC and WorldAtlas gives archaeological evidence from the 5th millennium BC; the start is therefore before 4500 BC, not in the stored 3000 - 1500 BC bucket (the Middle Helladic Aspis settlement is a later phase).", "value_page": null}]'::jsonb),
    ('e8e302a0-70b2-4346-ac75-340a4d6499a2'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/History', 'https://en.wikipedia.org/wiki/Argos,_Peloponnese', 'fields-wd1-2026-09-26b-s010:e8e302a0-70b2-4346-ac75-340a4d6499a2:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/History'' -> ''https://en.wikipedia.org/wiki/Argos,_Peloponnese''', '[{"source": "https://en.wikipedia.org/wiki/Argos,_Peloponnese", "url": "https://en.wikipedia.org/wiki/Argos,_Peloponnese", "quote": "A settlement of great antiquity, Argos has been continuously inhabited as at least a substantial village for the past 7,000 years.", "outcome": "found"}, {"source": "http://www.aspel.gr/argos.html", "url": "http://www.aspel.gr/argos.html", "quote": "Once the most powerful city in ancient Greece, Argos has been inhabited continuously for around 7000 years.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic Wikipedia article ''History''; the English Wikipedia article ''Argos, Peloponnese'' is the site''s own article (the city of Argos with its ancient history and monuments), and the Argolis site guide independently names the same city.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Argos, Peloponnese", "unreadable": false, "wikibase_item": "Q189901"}}]'::jsonb),
