    ('e9d94ed6-b8f1-489a-baa3-0934e14fff08'::uuid, 'period_start', '-1500', '-500', 'fields-wd1-2026-09-26b-s010:e9d94ed6-b8f1-489a-baa3-0934e14fff08:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-1500'' -> ''-500''', '[{"source": "https://en.wikipedia.org/wiki/Taksai_kurgans", "url": "https://en.wikipedia.org/wiki/Taksai_kurgans", "quote": "They are dated to circa 500 BCE", "outcome": "found"}, {"source": "https://welcome.kz/en/info-cities/west-kazakhstan/taksai-princess", "url": "https://welcome.kz/en/info-cities/west-kazakhstan/taksai-princess", "quote": "Researchers uncovered a complex of Saka and Sarmatian burial mounds dating back to around 500 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "The Taksai-1 kurgans in West Kazakhstan are Saka or Sauromatian burial mounds dated by English Wikipedia to circa 500 BCE and by the Kazakhstan tourism portal to around 500 BC (the golden-lady burial is put in the 6th-5th century BC, i.e. the same period); nothing supports the stored Bronze Age start of 1500 BC, so the start is -500, in the 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('eb2c2736-4019-4ef4-8e0d-5e444af09de7'::uuid, 'site_type', 'Megalithic structures', 'Reservoir/aqueduct/canal', 'fields-wd1-2026-09-26b-s010:eb2c2736-4019-4ef4-8e0d-5e444af09de7:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic structures'' -> ''Reservoir/aqueduct/canal''', '[{"source": "https://traianvs.net/textos/presas_in.htm", "url": "https://traianvs.net/textos/presas_in.htm", "quote": "To this type belongs the dam of Puy Foradado in the important hydraulic system", "outcome": "found"}, {"source": "https://traianvs.net/textos/presas_in.htm", "url": "https://traianvs.net/textos/presas_in.htm", "quote": "It is a circular structure, with approximately 56 metres of development and reduced height (about 2 metres) used as diversion weir in the mentioned system. The upstream face is formed by four ashlar courses; it is the only visible masonry nowadays, since the reservoir is completely silted-up (Castillo 2002).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Puy_Foradado_Dam", "url": "https://en.wikipedia.org/wiki/Puy_Foradado_Dam", "quote": "The Puy Foradado Dam was a Roman arch-gravity dam in Zaragoza province", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "replace", "status": "CONFLICT", "reasoning": "TRAIANVS describes Puy Foradado as a small arch-gravity dam used as a diversion weir at the head of the Los Bañales water system, with a reservoir that is now silted up, and Wikipedia calls it a Roman arch-gravity dam. It is Roman water infrastructure, not a megalithic structure, so Reservoir/aqueduct/canal replaces the stored type.", "value_page": null}]'::jsonb),
