    ('eb56629d-c8e4-4f74-bebf-85b06ee5ba20'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s010:eb56629d-c8e4-4f74-bebf-85b06ee5ba20:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0122)", "decision": "clear", "status": "MISSING", "reasoning": "Historic Environment Scotland states that no-one knows who made Burghead Well or when; the Pictish fort around it is dated, the well itself is not, and the stored 1000 BC (bucket 1500 - 500 BC) has no source, so the field is emptied.", "value_page": null}]'::jsonb),
    ('eb56629d-c8e4-4f74-bebf-85b06ee5ba20'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Burghead', 'https://nl.wikipedia.org/wiki/Burghead_Well', 'fields-wd1-2026-09-26b-s010:eb56629d-c8e4-4f74-bebf-85b06ee5ba20:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Burghead'' -> ''https://nl.wikipedia.org/wiki/Burghead_Well''', '[{"source": "https://nl.wikipedia.org/wiki/Burghead_Well", "url": "https://nl.wikipedia.org/wiki/Burghead_Well", "quote": "De Burghead Well is een volledig in rots uitgehouwen ruimte met een bron, waarvan het doel niet duidelijk is.", "outcome": "found"}, {"source": "https://www.historicenvironment.scot/visit/all/burghead-well/", "url": "https://www.historicenvironment.scot/visit/all/burghead-well/", "quote": "No-one knows who made Burghead Well, when they made it, or what it was for.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0122)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the town of Burghead; the well has no English article, but the Dutch Wikipedia article Burghead Well is about the rock-cut well itself, which Historic Environment Scotland''s visitor page names as the same monument in Burghead.", "value_page": {"lang": "nl", "problem": null, "resolved_title": "Burghead Well", "unreadable": false, "wikibase_item": "Q2219143"}}]'::jsonb),
    ('ebf764c6-27e7-45d9-834a-3f660c82193b'::uuid, 'source_url', 'www.wanderleb.com/blog/sfireh-temples', 'https://de.wikipedia.org/wiki/Hosn_Sfiri', 'fields-wd1-2026-09-26b-s010:ebf764c6-27e7-45d9-834a-3f660c82193b:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''www.wanderleb.com/blog/sfireh-temples'' -> ''https://de.wikipedia.org/wiki/Hosn_Sfiri''', '[{"source": "https://de.wikipedia.org/wiki/Hosn_Sfiri", "url": "https://de.wikipedia.org/wiki/Hosn_Sfiri", "quote": "Dieser Hauptbezirk von Hosn Sfiri liegt auf etwa 1200 Metern Seehöhe auf einem Bergsattel.", "outcome": "found"}, {"source": "https://bam.agendaculturel.com/explore/monuments/sfireh-temple", "url": "https://bam.agendaculturel.com/explore/monuments/sfireh-temple", "quote": "The Sfireh Temple complex lies about 35 kilometers outside of Tripoli", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored value is not a URL. The German Wikipedia article Hosn Sfiri is the site''s own article, about the temple group above Sfireh village, and BAM Agenda Culturel describes the same Sfireh temple complex independently.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Hosn Sfiri", "unreadable": false, "wikibase_item": "Q2720179"}}]'::jsonb),
