    ('ec429566-4a7e-430c-a1a3-da90dc9f695f'::uuid, 'period_start', '1', '501', 'fields-wd1-2026-09-26b-s010:ec429566-4a7e-430c-a1a3-da90dc9f695f:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''1'' -> ''501''', '[{"source": "https://www.cntraveller.in/story/arvalem-caves-goa-the-story-behind-the-rock-cut-caves/", "url": "https://www.cntraveller.in/story/arvalem-caves-goa-the-story-behind-the-rock-cut-caves/", "quote": "The history of these caves dates back to the 6th century, when they are believed to have been carved.", "outcome": "found"}, {"source": "https://timesofindia.indiatimes.com/travel/destinations/these-rock-cut-caves-in-goa-once-sheltered-the-pandavas/articleshow/101606095.cms", "url": "https://timesofindia.indiatimes.com/travel/destinations/these-rock-cut-caves-in-goa-once-sheltered-the-pandavas/articleshow/101606095.cms", "quote": "These caves hold historical and mythological significance and are believed to date back to the 6th or 7th century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0077)", "decision": "replace", "status": "MISSING", "reasoning": "Condé Nast Traveller India and the Times of India both date the carving of the Arvalem caves to the 6th century (TOI: 6th or 7th), so the start is the 6th century (501), in the 500–1000 AD bucket rather than the stored 1–500 AD one.", "value_page": null}]'::jsonb),
    ('ec429566-4a7e-430c-a1a3-da90dc9f695f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Arvalem_Caves', 'https://www.livehistoryindia.com/story/amazing-india/arvalem-caves', 'fields-wd1-2026-09-26b-s010:ec429566-4a7e-430c-a1a3-da90dc9f695f:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Arvalem_Caves'' -> ''https://www.livehistoryindia.com/story/amazing-india/arvalem-caves''', '[{"source": "https://www.livehistoryindia.com/story/amazing-india/arvalem-caves", "url": "https://www.livehistoryindia.com/story/amazing-india/arvalem-caves", "quote": "Arvalem is a rare example of a man made cave complex cut out of laterite rock.", "outcome": "found"}, {"source": "https://www.cntraveller.in/story/arvalem-caves-goa-the-story-behind-the-rock-cut-caves/", "url": "https://www.cntraveller.in/story/arvalem-caves-goa-the-story-behind-the-rock-cut-caves/", "quote": "The Arvalem caves are located near the Arvalem Falls in Sanquelim, North Goa", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0077)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article does not exist and no Wikipedia in any language has an article on the caves (Wikidata links only a Commons category); Live History India''s article on the Arvalem Caves is a history page about this very site, and Condé Nast Traveller India confirms the site of that name.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ec47336a-5eeb-4b59-b60c-9ef6d1901934'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s010:ec47336a-5eeb-4b59-b60c-9ef6d1901934:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ec47336a-5eeb-4b59-b60c-9ef6d1901934'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s010:ec47336a-5eeb-4b59-b60c-9ef6d1901934:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Farley Green Wikipedia article dates the temple (in use some time before the end of the 1st century AD); the 2007 excavation report''s abstract says the date(s) when the temple and temenos were built cannot be precisely established and that ritual activity on the hilltop is most conclusive for the later Iron Age, so no two independent sources place the start in one bucket.", "value_page": null}]'::jsonb),
    ('ec47336a-5eeb-4b59-b60c-9ef6d1901934'::uuid, 'site_type', 'Temple complex', 'Temple', 'fields-wd1-2026-09-26b-s010:ec47336a-5eeb-4b59-b60c-9ef6d1901934:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Temple complex'' -> ''Temple''', '[{"source": "https://www.roman-britain.co.uk/places/farley_heath/", "url": "https://www.roman-britain.co.uk/places/farley_heath/", "quote": "A square temple within a temenos in flat country near Albury.", "outcome": "found"}, {"source": "https://www.nature.com/articles/144473b0", "url": "https://www.nature.com/articles/144473b0", "quote": "the temple consisted of a simple cella, or shrine, measuring 18 ft. internally, and surrounded by a corridor, or veranda, 8 ft. wide.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "Roman-Britain.org and the 1939 Nature report describe a single square Romano-Celtic temple (cella and ambulatory) in its temenos; the excavators found no other permanent structures within the enclosure, so Temple fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('ec47336a-5eeb-4b59-b60c-9ef6d1901934'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Farley_Green,_Surrey', 'https://www.roman-britain.co.uk/places/farley_heath/', 'fields-wd1-2026-09-26b-s010:ec47336a-5eeb-4b59-b60c-9ef6d1901934:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Farley_Green,_Surrey'' -> ''https://www.roman-britain.co.uk/places/farley_heath/''', '[{"source": "https://www.roman-britain.co.uk/places/farley_heath/", "url": "https://www.roman-britain.co.uk/places/farley_heath/", "quote": "This rural temple at Farley Heath may mark the border between two British iron-age tribes", "outcome": "found"}, {"source": "https://www.nature.com/articles/144473b0", "url": "https://www.nature.com/articles/144473b0", "quote": "the site of the Roman temple on Farley Heath, Albury, Surrey", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hamlet of Farley Green; the temple has no Wikipedia article and the Historic England entry cannot be read by a plain GET, so Roman-Britain.org''s page on the Farley Heath temple is the readable page about the site itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ec838509-a1e6-4f6a-b216-3f1791c16d67'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s010:ec838509-a1e6-4f6a-b216-3f1791c16d67:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
