    ('ed3e4264-7d20-4bbc-ba73-2d11563f2006'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s010:ed3e4264-7d20-4bbc-ba73-2d11563f2006:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ed3e4264-7d20-4bbc-ba73-2d11563f2006'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s010:ed3e4264-7d20-4bbc-ba73-2d11563f2006:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "clear", "status": "MISSING", "reasoning": "Roman-Britain.co.uk states there is ''no conclusive dating evidence'' for the enclosure and Wikipedia only says it is ''believed'' to be Iron Age; no source gives a securely attested start, so the stored -1000 cannot be sourced.", "value_page": null}]'::jsonb),
    ('ed3e4264-7d20-4bbc-ba73-2d11563f2006'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s010:ed3e4264-7d20-4bbc-ba73-2d11563f2006:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Carrock_Fell", "url": "https://en.wikipedia.org/wiki/Carrock_Fell", "quote": "Carrock Fell is also the site of an Iron Age hill fort which crowns the summit.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/carrock-fell-hillfort/", "url": "https://www.roman-britain.co.uk/places/carrock-fell-hillfort/", "quote": "While often considered an unfinished or slighted Iron Age hillfort due to irregular gaps in the rampart", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Roman-Britain.co.uk describe the site as an Iron Age hill fort (univallate stone-built enclosure); Fort is the most specific canonical type for a hillfort.", "value_page": null}]'::jsonb),
    ('ed3e4264-7d20-4bbc-ba73-2d11563f2006'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Carrock_Fell', 'https://www.megalithic.co.uk/article.php?sid=7481', 'fields-wd1-2026-09-26b-s010:ed3e4264-7d20-4bbc-ba73-2d11563f2006:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Carrock_Fell'' -> ''https://www.megalithic.co.uk/article.php?sid=7481''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7481", "url": "https://www.megalithic.co.uk/article.php?sid=7481", "quote": "Site Name: Carrock Fell Country: England County: Cumbria Type: Hillfort", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/carrock-fell-hillfort/", "url": "https://www.roman-britain.co.uk/places/carrock-fell-hillfort/", "quote": "The Carrock Fell site features well-preserved earthwork remains of a univallate, stone-built enclosure covering 1.94 hectares.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the mountain (geology, mining, Dickens) with one paragraph on the fort; the Megalithic Portal entry is about the hillfort itself, which Roman-Britain.co.uk also describes. The Oxford Atlas of Hillforts did not respond and Historic England is unreadable to the checker.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ed7bb62e-95da-4f8a-9c42-869be8bfe912'::uuid, 'period_name', '3000 - 1500 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s010:ed7bb62e-95da-4f8a-9c42-869be8bfe912:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start -5000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ed7bb62e-95da-4f8a-9c42-869be8bfe912'::uuid, 'period_start', '-2000', '-5000', 'fields-wd1-2026-09-26b-s010:ed7bb62e-95da-4f8a-9c42-869be8bfe912:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-2000'' -> ''-5000''', '[{"source": "https://dergipark.org.tr/en/pub/adalya/article/681051", "url": "https://dergipark.org.tr/en/pub/adalya/article/681051", "quote": "the first layer dates to the early phase of the Middle Chalcolithic sometime around the early fifth millennium BC, while the other represents the Late Bronze Age.", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/tlos/", "url": "https://www.lycianmonuments.com/tlos/", "quote": "Archaeological research conducted in Tlos and its surrounding region indicates that the area has been inhabited since the 10th millennium BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators'' peer-reviewed report (Adalya 22, 2019) dates the earliest cultural layer beneath the stadium on the edge of the Tlos acropolis to the early fifth millennium BC (Middle Chalcolithic), and Lycian Monuments puts habitation of Tlos and its area as early as the 10th millennium BCE; both lie before 4500 BC, so the stored c. 2000 BC bucket is too late. The value is the site''s own attested first occupation, the 5th millennium BC.", "value_page": null}]'::jsonb),
    ('ed7bb62e-95da-4f8a-9c42-869be8bfe912'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s010:ed7bb62e-95da-4f8a-9c42-869be8bfe912:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Tlos", "url": "https://en.wikipedia.org/wiki/Tlos", "quote": "was an ancient Lycian city near the modern town of Seydikemer in the Mugla Province of southern Turkey", "outcome": "found"}, {"source": "https://muze.gov.tr/muze-detay?SectionId=TLO02&DistId=MRK", "url": "https://muze.gov.tr/muze-detay?SectionId=TLO02&DistId=MRK", "quote": "The ancient city of Tlos is located within the borders of Yakaköy in the Seydikemer district of Muğla", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Turkish Ministry of Culture''s museum portal both describe Tlos as an ancient city (one of the six principal cities of the Lycian League); nothing describes it as megalithic stones.", "value_page": null}]'::jsonb),
    ('ed8ffc34-ab81-4b4d-b852-ae20205fb2b5'::uuid, 'period_name', '< 4500 BC', NULL, 'fields-wd1-2026-09-26b-s010:ed8ffc34-ab81-4b4d-b852-ae20205fb2b5:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ed8ffc34-ab81-4b4d-b852-ae20205fb2b5'::uuid, 'period_start', '-300000', NULL, 'fields-wd1-2026-09-26b-s010:ed8ffc34-ab81-4b4d-b852-ae20205fb2b5:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''-300000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "clear", "status": "MISSING", "reasoning": "The cave''s Neanderthal occupation is dated by ESR/U-series to between 273 ± 26 ka and 146 ± 34 ka (and ''about 300,000 years ago'' by the University of Valencia), but every source states these ages only as ka or ''years ago'', which cannot be read as a year; with no two sources giving a readable start year, the field is emptied.", "value_page": null}]'::jsonb),
    ('edb4cd03-cbf2-412f-9861-bb88db0d2027'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s010:edb4cd03-cbf2-412f-9861-bb88db0d2027:period_name', 'fields-wd1-2026-09-26b-s010 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('edb4cd03-cbf2-412f-9861-bb88db0d2027'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s010:edb4cd03-cbf2-412f-9861-bb88db0d2027:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "The only dating comes from the excavators Arkush and Ikehara (a Late Intermediate Period site, ca. AD 1100-1450; fortifications built AD 1400-1490), which is one source family; no second independent source dates the start, and the stored AD 1 contradicts it, so the field is emptied.", "value_page": null}]'::jsonb),
    ('edb4cd03-cbf2-412f-9861-bb88db0d2027'::uuid, 'site_type', 'City/town/settlement', 'Fortress', 'fields-wd1-2026-09-26b-s010:edb4cd03-cbf2-412f-9861-bb88db0d2027:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''City/town/settlement'' -> ''Fortress''', '[{"source": "https://en.wikipedia.org/wiki/Pukarani_(Peru)", "url": "https://en.wikipedia.org/wiki/Pukarani_(Peru)", "quote": "to indicate ownership, \"the one with a fortress\", Hispanicized spelling", "outcome": "found"}, {"source": "https://www.elizabetharkush.com/past-projects/pucarani", "url": "https://www.elizabetharkush.com/past-projects/pucarani", "quote": "It is also one of the most impressive pre-Columbian hillforts in a region known for its hillforts.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Pukarani/Pucarani is a pukara, a walled hilltop stronghold: its name means ''the one with a fortress'' (Wikipedia), and the archaeologist Elizabeth Arkush, who mapped it in 2015, describes it as one of the most impressive pre-Columbian hillforts with 2.5 km of defensive walls up to 5 m high.", "value_page": null}]'::jsonb),
    ('edb4cd03-cbf2-412f-9861-bb88db0d2027'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pukarani_(Peru)', 'https://www.elizabetharkush.com/past-projects/pucarani', 'fields-wd1-2026-09-26b-s010:edb4cd03-cbf2-412f-9861-bb88db0d2027:source_url', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''https://en.wikipedia.org/wiki/Pukarani_(Peru)'' -> ''https://www.elizabetharkush.com/past-projects/pucarani''', '[{"source": "https://www.elizabetharkush.com/past-projects/pucarani", "url": "https://www.elizabetharkush.com/past-projects/pucarani", "quote": "Pucarani is located above the modern town of Nicasio on the Río Ramis.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pukarani_(Peru)", "url": "https://en.wikipedia.org/wiki/Pukarani_(Peru)", "quote": "The archaeological site of Pukarani was declared a National Cultural Heritage by", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article is about the mountain Pukarani and mentions the archaeological site only in passing; the project page of the archaeologist Elizabeth Arkush (University of Pittsburgh), who mapped the site in 2015, is about the Pucarani hillfort above Nicasio itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
