    ('ee80f50f-49c5-49c1-b3a6-76cce8d757a3'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s010:ee80f50f-49c5-49c1-b3a6-76cce8d757a3:site_type', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://delphi.culture.gr/archaelogical-site/monuments/", "url": "https://delphi.culture.gr/archaelogical-site/monuments/", "quote": "Monuments The Sicyonian Treasury The altar of the Chiots The Theban Treasury The Cyrenaean Treasury The Stoa/Portico of the Athenians The Stadium The Gymnasium The Athenian Treasury The Kastalian Spring The Tholos The theater of Delphi The Siphnian Treasury The Treasury of the Massaliots", "outcome": "found"}, {"source": "https://perseus-aa.github.io/items/aa_170.html", "url": "https://perseus-aa.github.io/items/aa_170.html", "quote": "Delphi, Treasury of the Massalians (Building) Temple-like building; in the center the Sanctuary of Athena Pronaia (Marmaria), east of the Tholos.", "outcome": "found"}, {"source": "https://topostext.org/place/385225SMaT", "url": "https://topostext.org/place/385225SMaT", "quote": "Massaliot treasury, fine marble naiskos by the Tholos, probably the treasury of Massalia/Marseilles, Marmaria, Delphi", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "CONFLICT", "reasoning": "The treasury is a small votive marble building dedicated by Massalia in the sanctuary of Athena Pronaia, not a megalithic structure: the Ministry of Culture''s Delphi site lists it among the site''s Monuments, Perseus calls it a temple-like treasury building and ToposText a marble naiskos; Monument is the canonical type that holds.", "value_page": null}]'::jsonb),
