    ('ef1ee8c0-f6bd-4886-bd66-8a6106ac5ca4'::uuid, 'period_start', '-3500', '-2900', 'fields-wd1-2026-09-26b-s010:ef1ee8c0-f6bd-4886-bd66-8a6106ac5ca4:period_start', 'fields-wd1-2026-09-26b-s010 (wd1-replace): ''-3500'' -> ''-2900''', '[{"source": "https://voices.uchicago.edu/ochre/project/shengavit/", "url": "https://voices.uchicago.edu/ochre/project/shengavit/", "quote": "was continuously occupied from about 2900-2450 BC. Its remains are those of the second phase (KA2) of the Kura-Araxes cultural tradition.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Shengavit_(site)", "url": "https://en.wikipedia.org/wiki/Shengavit_(site)", "quote": "It was inhabited during a series of settlement phases from around 3000 BC cal to 2500 BC cal", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavators'' project archive (Simonyan and Rothman, final report 2023) dates the continuous occupation to about 2900-2450 BC, a KA2 Kura-Araxes site, and Wikipedia gives settlement phases from around 3000 BC; the older c. 3500 BC estimate is not supported by the radiocarbon sequence, so the start (-2900) lies in 3000-1500 BC, not in the stored 4500-3000 BC bucket.", "value_page": null}]'::jsonb);
